COLLDATA("sharhsunnaur","ur",[[1036,"سیدنا عمر بن خطاب رضی اللہ عنہ جب مکہ تشریف لاتے تو دو رکعت نماز پڑھاتے، پھر سلام پھیرنے کے بعد کہتے: اے اہل مکہ! نماز مکمل کر لو، بے شک ہم تو مسافر لوگ ہیں۔","",{"k":"سنده صحيح: أخرجه مالك في المؤطأ: 349","e":"امام مالک رحمہ اللہ نے باشندگان مکہ کے متعلق کہا: یہ لوگ حج کرتے وقت منی میں دو رکعتیں پڑھیں گے تا آنکہ مکہ لوٹ جائیں اور منی میں رہائش پذیر شخص منی میں مکمل نماز پڑھے گا، اسی طرح میدان عرفات میں مستقل سکونت پذیر شخص عرفات میں پوری نماز پڑھے گا۔ امام بغوی رحمہ اللہ نے کہا: اکثر اہل علم کا موقف یہ ہے کہ مکہ کے باسی افراد مقام منی اور میدان عرفات میں قصر نماز نہیں پڑھیں گے۔"}],[1037,"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم، سیدنا ابوبکر، سیدنا عمر، سیدنا عثمان رضی اللہ عنہم کی رفاقت میں سفر کیے ہیں، یہ حضرات نماز ظہر و عصر دو دو رکعتیں پڑھتے تھے اور ان سے پہلے اور بعد میں کچھ نہیں پڑھتے تھے۔ سیدنا ابن عمر رضی اللہ عنہ نے کہا: اگر میں نے دوران سفر فرض نمازوں سے پہلے اور بعد میں کچھ پڑھنا ہوتا تو میں انھیں ہی مکمل ادا کر لیتا۔","",{"k":"صحيح: أخرجه الترمذى: 544"}],[1038,"جناب عیسیٰ بن حفص اپنے والد حفص بن عاصم سے بیان کرتے ہیں کہ انھوں نے کہا: ہم سیدنا عبداللہ بن عمر رضی اللہ عنہ کے ساتھ ایک سفر میں تھے، انھوں نے ہمیں دو رکعت نماز ظہر پڑھائی، پھر اٹھ کر گئے اور اپنے پالان کی لکڑی کے ساتھ ٹیک لگا کر بیٹھ گئے تو کچھ لوگوں کو اپنے بعد کھڑے ہو کر نماز پڑھتے دیکھا تو پوچھا: یہ کیا کر رہے ہیں؟ میں نے کہا: سنتیں پڑھ رہے ہیں، تو انھوں نے کہا: مجھے سنتیں پڑھنا ہوتیں تو میں نماز ہی پوری پڑھتا، پھر کہا: اے میرے بھتیجے! میں سفر میں اللہ کے رسول صلی اللہ علیہ وسلم کی صحبت میں رہا یہاں تک کہ اللہ نے آپ کو وفات دی، آپ نے دو رکعت سے زیادہ نہیں پڑھیں، پھر میں سیدنا ابوبکر رضی اللہ عنہ کی صحبت میں سفر کرتا رہا یہاں تک کہ وہ بھی وفات پاگئے، انھوں نے بھی دو رکعت سے زیادہ نہیں پڑھیں، پھر سیدنا عمر رضی اللہ عنہ کے ساتھ رہا، تو انھوں نے بھی دو رکعت سے زیادہ نہیں پڑھیں، یہاں تک کہ اللہ تعالیٰ نے ان کو بھی وفات دی، اور میں سیدنا عثمان رضی اللہ عنہ کے ساتھ رہا تو انھوں نے بھی دو سے زیادہ نہ پڑھیں، اللہ تعالیٰ نے فرمایا ہے:\n﴿ لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ ﴾ [سورہ احزاب: ۲۱]\n’’تمھارے لیے اللہ کے رسول کی زندگی بہترین نمونہ ہے۔‘‘","",{"k":"أخرجه مسلم: 689"}],[1039,"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں: میں رسول اللہ صلی اللہ علیہ وسلم کے ساتھ سفر میں رہا۔ آپ دو رکعت سے زیادہ نہیں پڑھتے تھے، میں نے سیدنا ابوبکر، عمر، عثمان رضی اللہ عنہم کے ساتھ سفر کیے ہیں ان کا طرز عمل بھی یہی تھا۔","",{"k":"أخرجه البخارى: 1102، و مسلم: 689","e":"جناب عطیہ عوفی سیدنا ابن عمر رضی اللہ عنہ سے بیان کرتے ہیں اور وہ اللہ کے رسول صلی اللہ علیہ وسلم کے متعلق بیان کرتے ہیں کہ آپ سفر میں نوافل پڑھا کرتے تھے۔(ضعیف، ترمذی: ۵۵۱، ۵۵۲) (ذہن نشین رہے کہ جامع ترمذی کی روایات کے الفاظ درج ذیل ہیں: عَنِ ابْنِ عُمَرَ قَالَ صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الظُّهْرَ فِي السَّفَرِ رَكْعَتَيْنِ وَبَعْدَهَا رَكْعَتَيْنِ...... سیدنا عبداللہ بن عمر رضی اللہ عنہ کہتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کے ساتھ سفر میں ظہر کی دو رکعتیں اور اس کے بعد بھی دو رکعتیں پڑھیں۔ عَنِ ابْنِ عُمَرَ قَالَ صَلَّيْتُ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْحَضَرِ وَالسَّفَرِ فَصَلَّيْتُ مَعَهُ فِي الْحَضَرِ الظُّهْرَ أَرْبَعًا وَبَعْدَهَا رَكْعَتَيْنِ وَصَلَّيْتُ مَعَهُ فِي السَّفَرِ الظُّهْرَ رَكْعَتَيْنِ وَبَعْدَهَا رَكْعَتَيْنِ وَالْعَصْرَ رَكْعَتَيْنِ وَلَمْ يُصَلِّ بَعْدَهَا شَيْئًا وَالْمَغْرِبَ فِي الْحَضَرِ وَالسَّفَرِ سَوَاءٌ ثَلَاثَ رَكَعَاتٍ لَا تَنْقُصُ فِي الْحَضَرِ وَلَا فِي السَّفَرِ هِيَ وِتْرُ النَّهَارِ وَبَعْدَهَا رَكْعَتَيْنِ...... سیدنا ابن عمر رضی اللہ عنہما سے مروی ہے، وہ کہتے ہیں: میں نے نبی صلی اللہ علیہ وسلم کے ساتھ سفر اور حضر میں نمازیں پڑھیں، آپ صلی اللہ علیہ وسلم حضر میں ظہر کی چار رکعتیں اور اس کے بعد بھی دو رکعتیں پڑھتے اور سفر میں ظہر کی دو اور اس کے بعد بھی دو رکعتیں پڑھتے تھے، پھر عصر کی دو رکعتیں پڑھتے اور ان کے بعد کچھ نہ پڑھتے، جبکہ مغرب کی نماز سفر و حضر میں تین رکعت ہی ہے، اس میں کوئی کمی نہیں اور یہ دن کے وتر ہیں، اس کے بعد آپ صلی اللہ علیہ وسلم دو رکعتیں پڑھتے تھے۔ جامع ترمذی کی یہ دونوں روایات ضعیف ہے، رسول اللہ صلی اللہ علیہ وسلم سفر میں عام نفلی نماز ادا کرتے تھے، البتہ فجر کی دو سنتیں سفر میں ادا کرنا آپ صلی اللہ علیہ وسلم سے ثابت ہے۔(م،م)"}],[1040,"سیدنا براء بن عازب رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کی معیت میں اٹھارہ سفر کیے ہیں، میں نے نہیں دیکھا کہ آپ نے ظہر سے قبل آفتاب ڈھلنے کے وقت (بعد از زوال) دو رکعتیں پڑھنا کبھی ترک کیا ہو۔","",{"k":"ضعيف: أخرجه ابوداود: 1222، والترمذى: 550"}],[1041,"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نماز پڑھی، یا کہا: میں نے اللہ کے رسول صلی اللہ علیہ وسلم کے ساتھ سفر و حضر میں نمازیں پڑھی ہیں، سفر میں آپ کے ساتھ ظہر کی چار رکعات اور اس کے بعد دو رکعتیں ادا کی ہیں جبکہ سفر میں ظہر کی دو رکعتیں اور اس کے بعد دو رکعتیں پڑھیں، اور عصر کی دو رکعتیں پڑھیں اور اس کے بعد کچھ نہیں پڑھا، نماز مغرب حضر و سفر میں برابر ہے، تین رکعات سے کم نہ زیادہ اور یہ دن کا وتر ہے، اس کے بعد دو رکعتیں پڑھی ہیں۔","",{"k":"ضعيف: أخرجه الترمذى: 552","e":"امام ابو عیسی ترمذی رحمہ اللہ نے کہا: یہ حدیث حسن ہے، نیز میں نے محمد بن اسماعیل بخاری رحمہ اللہ کو یہ کہتے ہوئے سنا ہے کہ ابن ابی لیلی نے اس سے پسندیدہ تر روایت بیان نہیں کی۔ امام بغوی رحمہ اللہ نے کہا: سفر میں رسول اللہ صلی اللہ علیہ وسلم کا سواری اور پڑاؤ کے مقام پر نفل ادا کرنے کا معاملہ بہت مشہور ہے۔ اکثر اہل علم نے حالت سفر میں نوافل پڑھنے کو پسند کیا ہے۔ جناب قاسم بن محمد، عروہ بن زبیر اور ابوبکر بن عبدالرحمن رحمہم اللہ وغیرہ سفر میں نفل نماز پڑھا کرتے تھے۔ علمائے کرام کے ایک گروہ نے اس بات کو پسند کیا ہے کہ سفر میں نوافل ادا نہ کیے جائیں بلکہ اللہ کی دی ہوئی رخصت کو قبول کیا جائے۔","f":"سفر میں فرائض سے پہلے یا بعد میں سنن راتبہ بحیثیت سنن مؤکدہ رسول اللہ صلی اللہ علیہ وسلم سے اور خلفائے راشدین کے عمل سے ثابت نہیں ہیں، ماسوائے فجر کی سنتوں اور وتر کے علاوہ ازیں اگر کوئی عام نفل کی حیثیت سے پڑھنا چاہے تو ممنوع نہیں ہے۔ نبی صلی اللہ علیہ وسلم دوران سفر اپنی سواری پر بھی نوافل پڑھا کرتے تھے۔ اس مسئلہ کا تعلق انسان کے اپنے ذوق سے ہے۔(ع،س)"}],[1042,"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم سفر میں اپنی سواری ہی پر رات کی نماز اشاروں سے پڑھ لیتے تھے، خواہ سواری کا رخ جس طرف ہو جاتا، مگر فرائض اس طرح نہیں پڑھتے تھے، اور وتر اپنی اونٹنی پر پڑھ لیتے تھے۔","",{"k":"أخرجه البخارى: 1000، ومسلم: 700"}],[1043,"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ میں نے نبی صلی اللہ علیہ وسلم کو گدھے پر سوار نماز پڑھتے ہوئے دیکھا جبکہ آپ کا چہرہ خیبر کی طرف تھا۔","",{"k":"أخرجه مسلم: 700"}],[1044,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے مجھے کسی کام کے لیے بھیجا، میں واپس آیا اور دیکھا کہ آپ اپنے اونٹنی پر نماز پڑھ رہے تھے اور آپ کا رخ مشرق کی طرف تھا اور آپ سجدے کے لیے رکوع سے زیادہ جھکتے تھے۔","",{"k":"هذا حديث صحيح: أخرجه الترمذى: 351، وابوداود: 1227","e":"امام بغوی رحمہ اللہ نے کہا: اہل علم صحابہ کرام اور بعد کے ادوار کے علمائے کرام اس بات پر متفق نظر آتے ہیں کہ دوران سفر میں سواری پر نفل پڑھنا جائز ہے جبکہ سواری اپنی منزل کی طرف رواں دواں ہو البتہ فرائض کی ادائیگی زمین پر اتر کر کی جائے گی۔ سواری پر وتر پڑھنے کے مسئلہ میں علمائے کے درمیان اختلاف پایا جاتا ہے، علماء وفضلاء کی اکثریت جواز کی قائل ہے، مثلاً سیدنا علی رضی اللہ عنہ، عبداللہ بن عباس رضی اللہ عنہ اور سیدنا ابن عمر رضی اللہ عنہ وغیرہ نیز عطاء بن ابی رباح، مالک، شافعی، احمد اور اسحاق رحمہم اللہ وغیرہ کا یہ موقف ہے۔ اہل رائے سواری پر وتر پڑھنے کے قائل نہیں، جناب نخعی رحمہ اللہ نے کہا: صحابہ کرام فرائض اور وتر زمین پر ادا کیا کرتے تھے۔ سفر تھوڑا ہو یا زیادہ اکثر علماء کے نزدیک سواری پر نوافل ادا کرنا جائز ہے۔ امام اوزاعی، امام شافعی رحمہ اللہ اور اہل الرائے یہی موقف رکھتے ہیں۔ امام مالک رحمہ اللہ کہتے ہیں: نوافل کی ادائیگی صرف اتنے سفر میں درست ہے جو حد قصر کو پہنچتا ہو۔ اگر ممکن ہو تو جب کوئی شخص سواری پر نفل ادا کرنا چاہتا ہو تو اسے قبلہ رخ ہو کے نیت باندھنی چاہیے، بعد ازیں وہ قراءت اور رکوع و سجود بجالائے خواہ اس کی سواری کا رخ جس طرف بھی ہو، سواری پر نماز پڑھنے والا آدمی رکوع اور سجدہ اشاروں سے کرے گا، رکوع کی نسبت سجدہ زیادہ جھکا ہوا ہونا چاہیے۔ سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب سفر میں ہوتے اور نفل پڑھنا چاہتے تو اپنی اونٹنی کو قبلہ رخ کرتے اور تکبیر تحریمہ کہ کر نماز شروع کر لیتے، پھر نماز پڑھتے رہتے خواہ سواری کا رخ کسی بھی طرف ہوتا رہتا۔(حسن، ابوداود: ۱۲۲۵) امام اوزاعی رحمہ اللہ پیدل چلنے والے شخص کے لیے نماز پڑھنا جائز سمجھتے ہیں خواہ مسافر ہو یا مقیم، اسی طرح جانور پر سوار آدمی جو شہر سے کسی غرض اور ضرورت کے لیے نکلا ہے نماز پڑھ سکتا ہے۔ امام بغوی رحمہ اللہ کہتے ہیں: کشتی میں سفر کرنے والا شخص کھڑے ہو کر نماز پڑھے مگر یہ کہ اس کا سر چکرانے لگے اور کھڑے ہو کر نماز پڑھنا اس کے لیے ممکن نہ رہے۔ امام ابو حنیفہ رحمہ اللہ نے کہا: کشتی میں سفر کرنے والے شخص کو اختیار حاصل ہے کھڑے ہو کر نماز پڑھے خواہ بیٹھ کر۔ امام حاکم رحمہ اللہ نے اپنی کتاب ’’مستدرک‘‘ میں صحیحین کی شرط پر ایک روایت سیدنا ابن عمر رضی اللہ عنہ کے واسطے سے ذکر کی ہے۔ انھوں نے کہا: نبی صلی اللہ علیہ وسلم سے دریافت کیا گیا: کشتی میں میں کس طرح نماز ادا کروں؟ آپ نے فرمایا: ’’کھڑے ہو کر نماز ادا کرو الا یہ کہ تمھیں ڈوب جانے کا خدشہ ہو۔‘‘(مستدرک حاکم: ۱۰۱۹، قال الذھبی: ھو علی شرط مسلم)"}],[1045,"سیدنا عبداللہ بن عمر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم کو جب (منزل مقصود تک) جلدی پہنچنا ہوتا تو مغرب اور عشاء کو اکٹھا کر لیتے۔","",{"k":"أخرجه البخارى: 1091، ومسلم: 703"}],[1046,"سیدنا انس رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم کو جب کسی منزل پر جلدی پہنچنا ہوتا تو ظہر کی نماز عصر کے اول وقت تک لیٹ کر کے دونوں کو اکٹھا پڑھتے، اسی طرح مغرب کی نماز کو مؤخر کرتے اور شفق کے غروب ہونے کے وقت مغرب اور عشاء کو ایک ساتھ پڑھتے۔","",{"k":"أخرجه البخارى: 1111، و مسلم: 704"}],[1047,"جناب ابو طفیل عامر بن واثلہ کہتے ہیں: سیدنا معاذ بن جبل رضی اللہ عنہ نے انھیں بتایا کہ وہ جنگ تبوک والے سال رسول اللہ صلی اللہ علیہ وسلم کے ہمراہ نکلے، رسول اللہ صلی اللہ علیہ وسلم دوران سفر ظہر و عصر اور مغرب و عشاء کی نمازیں جمع کرتے تھے، سیدنا معاذ رضی اللہ عنہ نے کہا: ایک روز آپ نے نماز ظہر کو مؤخر کیا، پھر تشریف لائے تو ظہر و عصر کو ایک ساتھ ادا فرمایا، پھر خیمے میں داخل ہو گئے، پھر آئے اور مغرب و عشاء کو اکٹھا ادا کیا، پھر ارشاد فرمایا: ’’تم کل ان شاء اللہ مقام تبوک کے چشمے پر ہوگے اور تم وہاں دن چڑھے پہنچو گے، جو بھی پہلے پہنچے وہ میرے آنے سے قبل چشمے کے پانی کو مت چھوئے۔‘‘ راوی نے کہا: ہم جب وہاں پہنچے تو دو شخص پہلے پہنچ چکے تھے اور چشمے سے جوتی کے تسمے کی طرح معمولی سا پانی رس رہا تھا۔ رسول اللہ صلی اللہ علیہ وسلم نے ان دونوں سے دریافت فرمایا: ’’کیا تم نے پانی کو چھوا ہے؟‘‘ انھوں نے جواب دیا: جی ہاں۔ تو آپ نے ڈانٹا اور جو اللہ کو منظور تھا کہا، پھر لوگوں نے چشمے کے پانی سے چلو بھر بھر کے ایک برتن میں کچھ پانی جمع کیا، پھر اس پانی سے آپ صلی اللہ علیہ وسلم نے اپنا چہرہ مبارک اور اپنے ہاتھ دھوئے اور پانی کو واپس چشمے میں ڈال دیا، اس طرح کرنے سے بہت زیادہ پانی جاری ہو گیا اور لوگوں نے پانی خوب سیر ہو کر پیا، بعد ازاں آپ صلی اللہ علیہ وسلم نے فرمایا: ’’بہت ممکن ہے اے معاذ! اللہ آپ کو عمر دراز عطا فرمائے اور آپ اس علاقے کو باغات سے سرسبز و شاداب پائیں۔‘‘","",{"k":"أخرجه مسلم: 706","e":"«تَبِضُّ» ’’قطرہ قطرہ پانی نکلنا، پانی کا کسی چیز سے رسنا۔‘‘ (ضَبَّ) کا معنی بھی یہی ہے اور یہ لفظ بَضَّ سے مقلوب ہے، معنی دونوں کا ایک ہے۔"}],[1048,"سیدنا عبداللہ بن عباس رضی اللہ عنہ سے روایت ہے انھوں نے کہا: میں تمھیں اللہ کے رسول صلی اللہ علیہ وسلم کی سفری نماز کے متعلق نہ بتاؤں؟ جب آپ زوال آفتاب کے وقت اپنی منزل میں ہوتے تو کوچ کے بعد ظہر اور عصر دونوں نمازوں کو اکٹھا ادا فرما لیتے اور جب زوال آفتاب سے پہلے سفر کا ارادہ فرماتے تو ظہر کو مؤخر کر دیتے حتی کہ عصر کے وقت میں ظہر اور عصر دونوں نمازوں کو جمع فرماتے، راوی نے کہا: میرا خیال ہے سیدنا ابن عباس رضی اللہ عنہ نے مغرب اور عشاء کے بارے میں بھی ایسے ہی کہا۔","",{"k":"ضعيف: أخرجه الامام الشافعى في المسند: 198، شرح كے آغاز ميں مذكورہ حديث ديكهيں۔","e":"امام بغوی رحمہ اللہ نے کہا: اہل علم کے درمیان اس بات میں اختلاف پایا جاتا ہے کہ سفر کے دوران میں نماز ظہر اور نماز عصر نیز نماز مغرب اور نماز عشاء میں جمع تقدیم و تاخیر جائز ہے یا نہیں؟ اہل علم کی کثیر تعداد جواز کا رجحان رکھتی ہے مثلاً ابن عباس رضی اللہ عنہ، عطاء بن ابی رباح، سالم بن عبداللہ، طاؤس، مجاہد، شافعی، احمد اور اسحاق رحمہم اللہ وغیرہ۔ جبکہ ایک گروہ کا خیال ہے کہ جمع تقدیم و تاخیر دونوں درست نہیں ہیں۔ جناب ابراہیم نخعی رحمہ اللہ سے یونہی مروی ہے اور وہ سیدنا عبداللہ بن مسعود رضی اللہ عنہ کے شاگردوں سے اس موقف کو بیان کرتے ہیں۔ حسن بصری رحمہ اللہ اور مکحول رحمہ اللہ نے بھی اسے ناپسند جانا ہے اور اہل الرائے کے نزدیک بھی یہ جائز نہیں ہے۔ انھوں نے کہا: دو نمازوں کو جمع کرنا مقصود ہو تو یوں کیا جائے کہ نماز ظہر کو اس کے آخری وقت تک مؤخر کیا جائے اور نماز عصر کو وقت شروع ہوتے ہی پڑھ لیا جائے (مغرب اور عشاء کو بھی اسی طرح ادا کیا جائے) وہ بیان کرتے ہیں کہ سیدنا سعد بن ابی وقاص رضی اللہ عنہ یہ دو نمازوں کو اسی طرح جمع کیا کرتے تھے۔ باقی رہا حجاج کرام کا نماز ظہر اور نماز عصر کو عرفہ میں اکٹھا پڑھنا اور نماز مغرب اور نماز عشاء کو مزدلفہ میں جمع کرنا تو یہ اتفاقی بات ہے۔ واللہ اعلم","f":"عَنْ مُعَاذِ بْنِ جَبَلٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ فِي غَزْوَةِ تَبُوكَ إِذَا زَاغَتِ الشَّمْسُ قَبْلَ أَنْ يَرْتَحِلَ جَمَعَ بَيْنَ الظُّهْرِ وَالْعَصْرِ وَإِنْ يَرْتَحِلْ قَبْلَ أَنْ تَزِيغَ الشَّمْسُ أَخَّرَ الظُّهْرَ حَتَّى يَنْزِلَ لِلْعَصْرِ وَفِي الْمَغْرِبِ مِثْلُ ذَلِكَ إِنْ غَابَتِ الشَّمْسُ قَبْلَ أَنْ يَرْتَحِلَ جَمَعَ بَيْنَ الْمَغْرِبِ وَالْعِشَاءِ وَإِنْ يَرْتَحِلْ قَبْلَ أَنْ تَغِيبَ الشَّمْسُ أَخَّرَ الْمَغْرِبَ حَتَّى يَنْزِلَ لِلْعِشَاءِ ثُمَّ جَمَعَ بَيْنَهُمَا\nسیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم غزوہ تبوک میں تھے، اگر روانگی سے پہلے سورج ڈھل جاتا تو ظہر و عصر ایک ساتھ پڑھ لیتے اور اگر آپ صلی اللہ علیہ وسلم سورج ڈھلنے سے پہلے روانہ ہو جاتے تو ظہر میں دیر کرتے، یہاں تک کہ عصر کے لیے اترتے (تب ظہر بھی پڑھتے) اور مغرب میں بھی ایسا ہی کرتے۔ اگر روانگی سے پہلے سورج ڈوب جاتا تو مغرب و عشاء کو ایک ساتھ پڑھتے اور اگر سورج غروب ہونے سے پہلے روانگی ہوتی تو مغرب میں دیر کرتے جب عشاء کی نماز کے لیے اترتے تو اس وقت مغرب بھی پڑھ لیتے۔(صحیح، ابوداود: ۱۲۰۸، ترمذی: ۵۵۳) (م،م) تقدیم و تاخیر کا معنی یہ ہے کہ دوسری نماز کو مقدم کر کے پہلی نماز کے وقت میں یا پہلی کو مؤخر کر کے دوسری کے وقت میں ادا کیا جائے اور یہ نبی صلی اللہ علیہ وسلم سے دوران سفر میں ثابت ہے۔ جمع صوری جسے جمع معنوی کہتے ہیں وہ یہ ہے کہ ایک نماز کو آخری وقت میں اور دوسری کو ابتدائی وقت میں پڑھا جائے، اس طرح نمازیں جمع بھی ہو جائیں گی اور ہر ایک اپنے اپنے وقت میں ہی ادا ہوگی۔(ع،س)"}],[1049,"سیدنا ابن عباس رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے بغیر خوف اور سفر کے نماز ظہر اور نماز عصر کو اکٹھا ادا فرمایا اور مغرب و عشاء کو جمع کیا۔ امام مالک رحمہ اللہ فرماتے ہیں: میرا خیال ہے کہ ایسا آپ نے بوجہ بارش کیا تھا۔","",{"k":"أخرجه البخارى: 543، و مسلم: 705","e":"لوگوں نے اختلاف کیا ہے کہ حضر میں بارش کے دوران میں ظہر و عصر اور مغرب و عشاء کو جمع کیا جا سکتا ہے یا نہیں؟ ایک گروہ نے جائز قرار دیا ہے اور سیدنا عبداللہ بن عمر رضی اللہ عنہ نیز عروہ، سعید بن مسیب، عمر بن العزیز، ابوبکر بن عبدالرحمن رحمہم اللہ اور مدینہ کے اکثر فقہائے کرام کا عمل اسی بات پر ہے۔ امام مالک، شافعی اور احمد رحمہم اللہ کا قول بھی یہی ہے البتہ امام شافعی رحمہ اللہ نے یہ شرط عائد کی ہے کہ جمع کرنے کی صورت میں پہلی نماز پڑھ کر دوسری نماز شروع کرتے وقت بارش برس رہی ہو، ابو ثور نے بھی یہی کہا ہے، ان دونوں بزرگوں کے علاوہ کسی نے بارش کی موجودگی کی شرط نہیں لگائی، البتہ یہ شرط ضرور لگائی ہے کہ جمع بین الصلاتین ایسی مسجد میں کیا جائے جس میں نماز پنج گانہ ادا ہوتی ہوں (گھر کی مسجد میں نہیں)۔ جبکہ امام مالک رحمہ اللہ کا خیال ہے کہ کیچڑ اور اندھیرے کی صورت میں نمازیں جمع کی جا سکتی ہیں۔ جناب عمر بن عبدالعزیز رحمہ اللہ کا بھی یہی موقف ہے۔ امام اوزاعی رحمہ اللہ اور اہل الرائے نے بوجہ بارش نمازیں جمع کرنے کی اجازت نہیں دی۔"}],[1050,"سیدنا عبداللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ظہر اور عصر کو مدینہ منورہ میں بغیر خوف اور بارش کے ملا کر پڑھا۔ ابوزبیر نے کہا: میں نے سعید بن جبیر سے پوچھا: آپ نے ایسا کیوں کیا؟ انھوں نے کہا: میں نے سیدنا عبداللہ بن عباس رضی اللہ عنہ سے یہی سوال کیا تھا جیسا تم نے مجھ سے پوچھا ہے تو انھوں نے کہا: تا کہ آپ کی امت میں سے کسی کو تکلیف نہ ہو۔","",{"k":"أخرجه مسلم: 705","e":"امام بغوی رحمہ اللہ نے کہا: یہ حدیث مبارکہ اس بات کی دلیل ہے کہ بغیر عذر کے نمازیں اکٹھی کی جا سکتی ہیں۔ سیدنا ابن عباس رضی اللہ عنہ نے یہ علت بیان کی ہے کہ امت پر دشواری ختم ہو۔ محدثین میں سے بہت کم اس بات کے قائل ہیں۔ بیان کیا جاتا ہے کہ جناب ابن سیرین رحمہ اللہ کسی معقول عذر کی وجہ سے نمازیں اکٹھی کر کے پڑھنے میں کوئی حرج نہیں جانتے تھے جب تک ان کو معمول نہ بنایا جائے۔ اکثر علماء کا خیال ہے کہ بغیر عذر نمازیں جمع کرنا جائز نہیں ہے، حسن بصری رحمہ اللہ اور عطاء رحمہ اللہ نے بیماری کی وجہ سے اکٹھی نمازیں پڑھنے کی اجازت دی ہے اور اس حدیث مبارکہ کا بھی یہی مطلب سمجھا ہے، امام مالک، احمد، اور اسحاق رحمہم اللہ کی رائے بھی یہی ہے۔","f":"جمہور علمائے حدیث کا اس سے استدلال یہ ہے کہ صرف بارش اور مرض کے علاوہ اگر کبھی کوئی شخص کسی معقول عذر کی وجہ سے نمازیں اکٹھی پڑھے تو جائز ہے مگر عادت نہ بنائی جائے جیسے کہ رسول اللہ صلی اللہ علیہ وسلم اور صحابہ سے ثابت ہے۔(ع،س) اس مقام پر درج ذیل مفید بحث محقق اور مترجم کی طرف سے پیش کی جاتی ہے، تاکہ قارئین اس مسئلہ میں سیر حاصل استفادہ کر لیں۔ جہاں اللہ تعالی نے اپنے بندوں پر دن میں پانچ نمازیں فرض کی ہیں، وہاں سفر کی صعوبتوں اور مجبوریوں کی بنا پر ظہر و عصر کو اور مغرب و عشا کو تقدیم و تاخیر کے ساتھ جمع کرنے کی رخصت بھی دی ہے، معلوم ہوا کہ سفر کے دوران ظہر اور عصر کو زوال آفتاب کے بعد سے لے کر غروب آفتاب تک اور مغرب و عشا کو غروب آفتاب سے نصف رات تک ادا کیا جا سکتا ہے۔ سیدنا انس رضی اللہ عنہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم جب زوال آفتاب سے پہلے سفر کا آغاز فرماتے تو نماز ظہر کو مؤخر کرتے، یہاں تک نماز عصر کا وقت ہو جاتا۔ پھر سواری سے نیچے تشریف لاتے اور ظہر و عصر دونوں کو اکٹھا ادا فرما لیتے اور اگر سفر کی ابتدا سے پہلے سورج زوال پذیر ہو جاتا تو نماز ظہر ادا کر کے سفر پر روانہ ہو جاتے۔(بخاری، مسلم) سیدنا معاذ بن جبل رضی اللہ عنہ کی روایت میں ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم زوال آفتاب کے بعد سفر کا ارادہ فرماتے تو ظہر و عصر کو اکٹھا ادا فرما لیتے تھے۔ (ابوداود، ترمذی) جب سیدنا عبداللہ بن عمر رضی اللہ عنہ کو سفر میں جانے کی جلدی ہوتی، تو مغرب و عشا کو شفق (سرخی) کے غائب ہونے (یعنی مغرب کا وقت ختم ہو جانے) کے بعد ادا کرتے اور کہتے: جب رسول اللہ صلی اللہ علیہ وسلم کو سفر میں چلنے کی جلدی ہوتی تھی تو آپ صلی اللہ علیہ وسلم مغرب اور عشا کو جمع کر لیتے تھے۔(بخاری، مسلم) قارئین کرام! میں نے بعض افراد کو غروب آفتاب کے بعد نماز ظہر یا نماز عصر ادا کرتے ہوئے دیکھا ہے، اسی طرح بعض لوگ فجر کی نماز کے لیے بیدار ہونے کی کوئی فکر نہیں کرتے، بلکہ بیدار ہونے کے باوجود پھر سے سونے کی کوشش کرتے ہیں اور طلوع آفتاب کے بعد نماز فجر ادا کر رہے ہوتے ہیں۔ دراصل یہ لوگ مقاصد شریعت اور روح اسلام سے غافل ہیں اور اپنی سہولتوں کے گرویدہ ہیں۔ اگر شریعت نے ظہر و عصر اور مغرب و عشا کو تقدیم و تاخیر کے ساتھ جمع کرنے کی اجازت دی ہے تو اس کا مطلب یہ نہیں کہ ہم خود اس رخصت میں مزید اضافہ کر لیں۔ عام حالات میں پانچ نمازوں کے اوقات مقرر ہیں لیکن سفر، بارش یا خوف کی بنا پر پانچ نمازوں کو تین اوقات میں ادا کیا جا سکتا ہے: (۱) سفر و حضر میں نماز فجر کا وقت ایک ہے۔ (۲) ظہر و عصر کو زوال آفتاب کے بعد سے لے کر غروب آفتاب تک ادا کرنا اور (۳) مغرب و عشا کو غروب آفتاب سے لے کر نصف رات تک ادا کرنا۔ جس طرح حضر میں پانچ اوقات کا خیال رکھا جاتا ہے، یہی معاملہ ان تین اوقات کا ہے، اس سے مزید رخصت کا راستہ نہ نکالا جائے۔ سیدنا عبداللہ بن عباس رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں: صَلَّى بِنَا بِالْمَدِينَةِ ثَمَانِيَةً، وَسَبْعًا. الظُّهْرَ وَالْعَصْرَ، وَالْمَغْرِبَ وَالْعِشَاءَ\nنبی کریم صلی اللہ علیہ وسلم نے مدینہ میں ہمیں اکٹھی آٹھ اور سات رکعتیں پڑھائیں، (یعنی ظہر و عصر کو اور مغرب و عشا کو جمع کر کے پڑھایا۔) (صحیح بخاری، صحیح مسلم) امام البانی رحمہ اللہ رقمطراز ہیں: حقیقت یہ ہے کہ میرے علم میں کوئی ایسی واضح حدیث نہیں ہے جو بارش میں نمازیں جمع کرنے پر دلالت کرے، البتہ سیدنا عبداللہ بن عباس رضی اللہ عنہ کی حدیث کے ان الفاظ (مِنْ غَيْرِ خَوْفٍ وَلَا مَطَرٍ) (یعنی بغیر کسی خوف اور بارش کے نمازیں جمع کرنا) سے معلوم ہوتا ہے کہ آپ صلی اللہ علیہ وسلم کے زمانے میں بارش کی وجہ سے نمازیں جمع کرنا معروف تھا اور اسی وجہ سے اس رخصت پر سلف کا عمل جاری رہا، جیسا کہ مصنف عبد الرزاق اور مصنف ابن ابی شیبہ میں بہت سے آثار منقول ہیں۔ امام نافع کہتے ہیں: ہمارے حکمرانوں کا یہ معمول تھا کہ وہ بارش والی رات میں مغرب کو مؤخر کر کے اور عشا کو جلدی کر کے دونوں نمازیں سرخی کے غائب ہونے سے پہلے ادا کر لیتے تھے، سیدنا عبداللہ بن عمر رضی اللہ عنہ ان کے ساتھ نماز پڑھتے تھے اور اس جمع میں کوئی حرج محسوس نہیں کرتے تھے۔ عبید اللہ کہتے ہیں: میں نے قاسم اور سالم کو دیکھا کہ وہ بھی بارش کے موسم میں ان امرا کے ساتھ نماز پڑھ لیتے تھے۔ (مصنف ابن ابی شیبہ) سیدنا عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں: جَمَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ الأُولَى وَالْعَصْرِ وَبَيْنَ الْمَغْرِبِ وَالْعِشَاءِ فَقِيلَ لَهُ، فَقَالَ: «صَنَعْتُ هَذَا لِكَيْ لَا تُحْرَجَ أُمَّتِي»...... رسول اللہ صلی اللہ علیہ وسلم نے ظہر و عصر اور مغرب و عشا کو جمع کر کے ادا کیا۔ جب آپ صلی اللہ علیہ وسلم سے وجہ پوچھی گئی تو فرمایا: ’’میں نے یہ نمازیں اس انداز میں اس لیے پڑھی ہیں تا کہ میری امت تنگی میں نہ پڑے۔‘‘(معجم طبرانی کبیر: ۱۰/۲۶۹/۱۰۵۲۵، صحیحہ: ۲۸۳۷) ظہر و عصر اور مغرب و عشا کو جمع کرنے کی دو صورتیں ہیں: جمع صوری: اس جمع کو کہتے ہیں جس میں ہر نماز کو اس کے اصل وقت میں ادا کیا جاتا ہے، یعنی ظہر اور مغرب کو آخری وقت میں اور عصر اور عشا کو پہلے وقت میں ادا کیا جاتا ہے۔ جمع حقیقی: جان بوجھ کر ایک نماز کو دوسری نماز کے وقت میں ادا کرنا، یعنی ظہر و عصر دونوں کو ظہر کے وقت میں یا عصر کے وقت میں ادا کرنا، اسی طرح مغرب و عشا دونوں کو مغرب کے وقت میں یا عشا کے وقت میں ادا کرنا۔ امام البانی رحمہ اللہ کی بحث کا خلاصہ یہ ہے: خوف، بارش اور سفر میں ظہر و عصر اور مغرب و عشا کو ایک دوسرے کے وقت میں ادا کرنا جائز ہے۔ حضر میں کسی عذر کی بنا پر اور بعض اوقات عذر کے بغیر بھی ایسا کرنا جائز ہے۔ جمع تقدیم: دو نمازوں کو پہلی نماز کے وقت میں ادا کرنا، جیسے ظہر و عصر کو ظہر کے وقت میں ادا کرنا جمع تاخیر: دو نمازوں کو دوسری نماز کے وقت میں ادا کرنا، مثلا ظہر و عصر کو عصر کے وقت میں ادا کرنا۔ امام البانی رحمہ اللہ لکھتے ہیں: امام شوکانی رحمہ اللہ کا خیال ہے کہ اس حدیث کو جمع صوری پر محمول کیا جائے گا، یعنی ظہر کو اس کے آخری وقت میں اور عصر کو اس کے پہلے وقت میں ادا کیا گیا۔ اس خیال کو ثابت کرنے کے لیے انھوں نے طویل بحث کی، حدیث کی تاویل کرنے میں تکلف برتا، مختلف امور سے اپنے موقف کا استدلال کرتے رہے اور اس سے جمع حقیقی کو ثابت نہ کیا جو کہ سفر والی احادیث سے صراحت کے ساتھ ثابت ہے۔ میں مناسب سمجھتا ہوں کہ قارئین کی توجہ اس نقطے کی طرف مبذول کراؤں کہ امام شوکانی رحمہ اللہ آپ صلی اللہ علیہ وسلم کی حدیث کے اس حصے کو ذہن نشین نہ کر سکے: «صَنَعْتُ هَذَا لِكَيْ لَا تُحْرَجَ أُمَّتِي» ’’میں نے یہ نمازیں اس انداز میں اس لیے پڑھی ہیں تا کہ میری امت تنگی میں نہ پڑے۔‘‘ یہ الفاظ جمع حقیقی کے حق میں واضح نص ہیں، کیونکہ شریعت کی اصطلاح میں امت سے گناہ اور حرام کام کا اثر ختم کرنے کے لیے (رَفْعَ الحَرَج) کا لفظ استعمال کیا جاتا ہے، جیسا کہ دوسری احادیث سے معلوم ہوتا ہے، مزید اس کو یوں سمجھیں کہ حرج اور تنگی نہ ہونے کی صورت میں مؤاخذہ کیا جائے گا، جیسا کہ بارش اور سردی کی وجہ سے نماز جمعہ اور نماز باجماعت ترک کرنے کی رخصت دی گئی ہے، جب سیدنا عبداللہ بن عباس رضی اللہ عنہ نے مؤذن کو جمعہ کے دن اذان میں ’’الصَّلَاةُ فِي الرِّحَالِ‘‘ (نماز گھروں میں ادا کر لو) کہنے کا حکم دیا تو بعض لوگوں نے اس کلمہ پر انکار کیا، اس پر سیدنا ابن عباس رضی اللہ عنہ نے کہا: ایسے لگتا ہے کہ تم لوگ اس جملے کا انکار کر رہے ہو، حالانکہ اس ہستی نے یہ الفاظ کہلوائے تھے جو مجھ سے بہتر ہے، ان کی مراد نبی کریم صلی اللہ علیہ وسلم کی ذات تھی۔ ایسے موسم میں نماز جمعہ ادا کرنا عزیمت ہے، لیکن میں ناپسند کرتا ہوں کہ تم لوگوں کو تنگی میں ڈال دوں۔(بخاری: ۶۱۶، ۶۶۸، ۹۰۱، موقوف الفاظ ابن ابی شیبہ (۲/۱۵۳) کے ہیں۔) نعیم بن نجام کہتے ہیں: سخت سردی تھی، صبح کی اذان ہونے لگی، میں اپنی بیوی کی چادر میں لیٹا ہوا تھا، میں نے کہا: کاش موذن ’’وَمَنْ قَعَدَ فَلَا حَرَجَ‘‘ کہہ دے (یعنی اگر کوئی نہ آئے تو اس پر کوئی حرج نہیں)۔ اتنے میں نبی کریم صلی اللہ علیہ وسلم کے موذن نے ’’وَمَنْ قَعَدَ فَلَا حَرَجَ‘‘ کہہ دیا۔(مسند احمد: ۴/۳۲۰) ہر کوئی جانتا ہے کہ جمعہ کی نماز باجماعت ادا کرنا واجب ہے۔ جب شریعت بارش کے دوران نہ آنے والوں سے حرج اور تنگی کی نفی کرے گی، تو یہ ایک نیا حکم قرار پائے گا۔ جب بارش والا عذر نہیں ہوگا تو نمازیوں کو بلانے کے لیے عام اذان ہوگی، جس میں کسی کو مستثنی نہیں کیا جائے گا۔ اسی طرح ہم کہتے ہیں: ہر نماز کو اس کے مقررہ وقت میں ادا کرنا واجب ہے، جیسا کہ بے شمار نصوص سے واضح ہوتا ہے۔ (جو آدمی جان بوجھ کر نماز کو اس کے وقت سے پہلے یا اس کا وقت گزر جانے کے بعد ادا کرے گا، وہ گنہگار ہوگا اور اس کی نماز قبول نہیں ہوگی)۔ لیکن آپ صلی اللہ علیہ وسلم نے دو نمازوں کو جمع کیا اور اپنی امت سے حرج اور تنگی کو دور کر دیا۔ یہ واضح دلیل ہے کہ آپ صلی اللہ علیہ وسلم کی جمع، حقیقی تھی۔ ان اصول و قرائن کے باوجود اس حدیث کو جمع صوری پر محمول کرنے سے اس حدیث کا متن بے مقصد ہو کر رہ جاتا ہے، جیسا کہ ہر انصاف پسند اور غور و فکر کرنے والے آدمی کی یہی رائے ہے، کیونکہ جمع صوری میں تو سرے سے کوئی حرج نہیں ہے۔ اس حدیث کی تاویل کرتے ہوئے اس کو جمع صوری پر محمول کرنا، اس بارے میں امام نووی رحمہ اللہ نے بلا مبالغہ درست کہا ہے کہ یہ تاویل باطل ہے، حدیث کے ظاہری مفہوم کے مخالف ہے، اس کی کوئی گنجائش نہیں۔ درج ذیل دو امور سے تاکید مزید پیدا ہوتی ہے: (اول) سیدنا عبداللہ بن عباس رضی اللہ عنہ کی حدیث میں یہ وضاحت کی گئی ہے کہ آپ صلی اللہ علیہ وسلم نے دشمنوں کے خوف اور بارش کے بغیر نمازیں جمع کی تھیں۔ اس سے قوی اشارہ ملتا ہے کہ دوران بارش آپ صلی اللہ علیہ وسلم کا جمع کرنا حاضرین کے نزدیک معروف تھا۔ لیکن کیا بارش کے دوران جمع صوری کرتے تھے؟ یقینا نہیں، سیدنا عبداللہ بن عمر رضی اللہ عنہ کے غلام امام نافع اس کے بارے میں کہتے ہیں: بارش والی رات کو ہمارے اُمرا مغرب کو مؤخر کر کے اور عشا کو معجل کر کے دونوں کو سرخی کے غروب سے پہلے ادا کر لیتے تھے۔ سیدنا عبداللہ بن عمر رضی اللہ عنہ بھی ان کے ساتھ نماز پڑھتے تھے اور ایسا کرنے میں کوئی حرج محسوس نہیں کرتے تھے۔ عبید اللہ، جو نافع سے یہ روایت بیان کرتے ہیں، کہتے ہیں: میں نے سالم اور قاسم کو بھی ان کے ساتھ نماز پڑھتے ہوئے دیکھا۔(مصنف ابن ابی شیبہ: ۲/۲۳۴ بسند صحیح غایة) میں (البانی) کہتا ہوں: ’’سرخی کے غائب ہونے سے پہلے نمازوں کو ادا کر لینا‘‘ اس سے واضح طور پر معلوم ہوتا ہے کہ وہ جمع حقیقی تھی، کیونکہ نماز مغرب کا وقت غروب شفق تک جاری رہتا ہے، جیسا کہ صحیح مسلم کی سیدنا عبداللہ بن عمر رضی اللہ عنہ کی حدیث سے معلوم ہوتا ہے، میں نے اس کی (صحیح ابی داود: ۴۲۵) میں تخریج کی ہے۔ (دوم) سیدنا عبداللہ بن عباس رضی اللہ عنہ کی حدیث میں نمازوں کو جمع کرنے کی یہ وجہ بیان کی گئی ہے: «صَنَعْتُ هَذَا لِكَيْ لَا تُحْرَجَ أُمَّتِي» ’’میں نے یہ نمازیں اس انداز میں اس لیے پڑھی ہیں تا کہ میری امت تنگی میں نہ پڑے۔‘‘ سفر میں نمازیں جمع کرنے کی بھی یہی وجہ بیان کی گئی ہے، جیسا کہ سیدنا معاذ رضی اللہ عنہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے غزوہ تبوک کے دوران ظہر و عصر اور مغرب و عشا کو جمع کر کے ادا کیا۔ ابو طفیل کہتے ہیں: میں نے پوچھا: آپ صلی اللہ علیہ وسلم کو کس چیز نے جمع کرنے پر آمادہ کیا؟ انھوں نے جواب دیا: آپ کا ارادہ یہ تھا کہ امت تنگی میں نہ پڑے۔(صحیح مسلم) میں نے (ارواء الغلیل: ۳/۳۱) میں اس کی تخریج کی ہے۔ ابوداود وغیرہ کی روایت میں ہے: یہ جمع تقدیم و تاخیر کے ساتھ تھی، یہی بات سیدنا انس رضی اللہ عنہ وغیرہ کی حدیث سے بھی ثابت ہے۔(دیکھئے: ارواء الغلیل: ۵۷۸، ۵۷۹) میں کہتا ہوں: اگر آپ سابقہ بحث ذہن نشین کر لیں تو آپ کو یقین ہو جائے گا کہ اس حدیث کی صحیح مراد جمع حقیقی ہی ہے، جس کے ذریعے امت کو بسا اوقات لاحق ہونے والی تنگی کو دور کیا جا سکتا ہے۔ رہا مسئلہ جمع صوری کا، تو سفر ہو یا حضر ہو، اس میں سرے سے کوئی حرج ہی نہیں ہے، (کیونکہ ہر نماز کو اس کے وقت پر ادا کیا جاتا ہے)۔ احناف نے اس حدیث کی تاویل کرتے ہوئے جمع حقیقی کو ناجائز قرار دیا ہے، لیکن جمہور علما و فقہا جمع حقیقی کے قائل ہیں، جمہور نے جتنے دلائل پیش کیے، ان میں جمع تقدیم کی بھی وضاحت ہے۔ یہ دلائل حنفیوں کی تاویلات کو باطل کرتے ہیں۔ بعض احادیث میں جمع تاخیر کا ذکر بھی ہے، جیسا کہ سیدنا انس رضی اللہ عنہ بیان کرتے ہیں: إِذَا عَجِلَ عَلَيْهِ السَّفَرُ يُؤَخِّرُ الظُّهْرَ إِلَى أَوَّلِ وَقْتِ الْعَصْرِ، فَيَجْمَعُ بَيْنَهُمَا وَيُؤَخِّرُ الْمَغْرِبَ حَتَّى يَجْمَعَ بَيْنَهَا وَبَيْنَ الْعِشَاءِ حِينَ يَغِيبُ الشَّفَقُ\nاگر نبی کریم صلی اللہ علیہ وسلم کو سفر میں جلدی ہوتی تو ظہر کو عصر کے ابتدائی وقت تک مؤخر کر کے دونوں کو اکٹھا (عصر کے وقت میں) ادا کرتے اور مغرب کو مؤخر کر کے عشا کے ساتھ اس وقت جمع کرتے، جب سرخی غروب ہو چکی ہوتی تھی۔(بخاری، مسلم) میں یہ کہنا مناسب سمجھوں گا کہ سیدنا عبداللہ بن عباس رضی اللہ عنہ کی حدیث میں آپ صلی اللہ علیہ وسلم نے جمع کی یہ علت بیان کی ہے: «صَنَعْتُ هَذَا لِكَيْ لَا تُحْرَجَ أُمَّتِي»...... ’’میں نے یہ نمازیں اس انداز میں اس لیے پڑھی ہیں تا کہ میری امت تنگی میں نہ پڑے۔‘‘ اس وجہ سے یہ معلوم ہوتا ہے کہ جب کوئی عذر، تنگی اور حرج ہو تو نمازوں کو جمع کر لینا جائز ہے، وگرنہ نہیں۔ افراد، حالات اور مقامات کو دیکھ کر عذر کا فیصلہ کیا جاتا ہے۔ سلف صالحین میں سے جن علما و فقہا نے ان احادیث سے استدلال کرتے ہوئے نمازوں کو علی الاطلاق جمع کرنے کی اجازت دی ہے، انھوں نے یہ شرط بھی لگائی ہے کہ اس کو عادت اور معمول نہ بنا لیا جائے، جیسا کہ شیعہ لوگوں نے کیا ہے۔ میرا خیال ہے کہ جو آدمی مساجد میں پانچوں نمازیں ان کے مقررہ اوقات میں باجماعت کرنے کا حریص ہوگا، وہ عذر کے بغیر اس حدیث پر عمل نہیں کرے گا۔ واللہ سبحانہ وتعالی اعلم۔(صحیحہ: ۲۸۳۴) رَحِمَ اللَّهُ الْأَلْبَانِيَّ رَحْمَةً وَّاسِعَةً. سیدنا معاذ بن جبل رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں: كَانَ فِي غَزْوَةِ تَبُوكَ إِذَا ارْتَحَلَ قَبْلَ زَيْغِ الشَّمْسِ، أَخَّرَ الظُّهْرَ إِلَى أَنْ يَجْمَعَهَا إِلَى الْعَصْرِ، فَيُصَلِّيهِمَا جَمِيعًا، وَإِذَا ارْتَحَلَ بَعْدَ زَيْغِ الشَّمْسِ، عَجَّلَ الْعَصْرَ إِلَى الظُّهْرِ، وَصَلَّى الظُّهْرَ وَالْعَصْرَ جَمِيعًا، ثُمَّ سَارَ وَكَانَ إِذَا ارْتَحَلَ قَبْلَ الْمَغْرِبِ أَخَّرَ الْمَغْرِبَ حَتَّى يُصَلِّيَهَا مَعَ الْعِشَاءِ، وَإِذَا ارْتَحَلَ بَعْدَ الْمَغْرِبِ، عَجَّلَ الْعِشَاءَ فَصَلَّاهَا مَعَ الْمَغْرِبِ\nرسول اللہ صلی اللہ علیہ وسلم غزوہ تبوک (کے سفر) میں تھے۔ اگر سورج ڈھلنے سے پہلے کوچ کر جاتے تو ظہر کی نماز کو مؤخر کرتے یہاں تک کہ اسے عصر کے ساتھ جمع کرتے اور دونوں کو اکٹھا پڑھتے اور اگر سورج کے ڈھلنے کے بعد سفر شروع کرتے تو ظہر کے ساتھ عصر بھی پڑھ لیتے اور پھر سفر شروع کرتے۔ اسی طرح اگر غروب آفتاب سے پہلے کوچ کر جاتے تو مغرب کو مؤخر کرتے، یہاں تک کہ اسے عشا کے ساتھ پڑھتے اور اگر غروب آفتاب کے بعد سفر شروع کرتے تو عشا کی نماز کو جلدی کر کے مغرب کے ساتھ ہی پڑھ لیتے۔(صحیح مسلم: ۷/۶۰، ابوداود: ۱۲۰۶، ۱۲۰۷، ترمذی: ۲/۴۳۸، نسائی: ۱/۹۸) یہ حدیث مبارکہ سفر میں جمع حقیقی کی انتہائی واضح دلیل ہے، بعض احباب سفر کے دوران بھی نمازوں کے جمع کر کے ادا کرنے کے قائل نہیں اور جن احادیث میں آتا ہے کہ آپ صلی اللہ علیہ وسلم نے ظہر و عصر اور مغرب و عشا کو جمع کیا، ان کو جمع صوری پر محمول کرتے ہیں، یعنی ظہر و عصر کو جمع کرنے کا مطلب یہ ہے کہ ظہر کو اس کے آخری وقت میں اور عصر کو اس کے اول وقت میں ادا کیا جائے، لیکن مذکورہ بالا حدیث اس حقیقت کا ٹھوس ثبوت ہے کہ ظہر کو عصر کے وقت میں اور عصر کو ظہر کے وقت میں ادا کرنا درست ہے۔ امام البانی رحمہ اللہ نے کہا: یہ حدیث مبارکہ کئی مسائل پر مشتمل ہے: (۱)...... عرفہ اور مزدلفہ کے علاوہ بھی سفر میں نمازیں جمع کر کے ادا کرنا جائز ہے، جمہور علما کا یہی مسلک ہے، مگر احناف نے جمع والی احادیث کو جمع صوری پر محمول کر کے جمہور کی مخالفت کی ہے، لیکن جمہور نے کئی طرح سے ان کا رد پیش کیا ہے، مثلا: (أ)...... جمع کو جمع صوری پر محمول کرنا احادیث کے ظاہری مفہوم کے مخالف ہے۔ (ب)...... جمع کی غرض و غایت لوگوں کو آسانی فراہم کرنا اور ان سے تنگی کو دور کرنا ہے، جیسا کہ صحیح مسلم کی روایت میں اس کی وضاحت کی گئی ہے کہ آپ صلی اللہ علیہ وسلم کی جمع کا مقصد امت سے حرج اور تنگی کو دور کرنا تھا۔ (ج)...... بعض احادیث میں جمع حقیقی کی وضاحت احناف کی تاویل کو باطل کر دیتی ہے، مثلا سیدنا انس رضی اللہ عنہ کی حدیث میں ہے: آپ صلی اللہ علیہ وسلم نے نماز ظہر اتنی مؤخر کی کہ عصر کا ابتدائی وقت ہو گیا، پھر ان دونوں کو جمع کر کے ادا کیا۔(مسلم) (د)...... اس باب کی حدیث بھی احناف کی تاویل کو رد کرتی ہے جس میں یہ وضاحت کر دی گئی ہے کہ آپ صلی اللہ علیہ وسلم کے سفر کا آغاز زوال آفتاب کے بعد ہوتا تو آپ صلی اللہ علیہ وسلم عصر کو جلدی کر کے ظہر کے ساتھ پڑھ لیتے، اسی طرح اگر آپ اپنے مقام سے مغرب کے بعد کوچ کرتے تو عشا کو جلدی کر کے مغرب کے ساتھ ادا کر لیتے۔ (۲)...... جمع تقدیم اور جمع تاخیر دونوں جائز ہیں، جیسا کہ امام شافعی رحمہ اللہ نے (الأم: ۱/۶۷) میں کہا اور اسی طرح امام احمد اور امام اسحاق رحمہم اللہ بھی ان دونوں صورتوں کے قائل ہے، ان کے بارے میں امام ترمذی رحمہ اللہ نے وضاحت کی ہے۔ (۳)...... پڑاؤ کی حالت میں نمازوں کو جمع کرنا جائز ہے، جیسا کہ جلدی نکلنے کی صورت میں اس کا جواز ملتا ہے۔ امام شافعی نے (الأم) میں امام مالک کی سند سے حدیث بیان کرنے کے بعد کہا: اس صورت میں آپ صلی اللہ علیہ وسلم پڑاؤ کی حالت میں تھے، نہ کہ چلنے کی حالت میں، کیونکہ حدیث کے الفاظ (دَخَلَ...... ثُمَّ خَرَجَ\nآپ داخل ہوئے...... پھر نکلے) سے معلوم ہوتا ہے کہ آپ کسی مقام پر اترے ہوئے تھے، لہذا مسافر چل رہا ہو یا اس نے کسی مقام پر پڑاؤ ڈالا ہوا ہو، اس کے لیے جمع کرنا جائز ہے۔ (پڑاؤ کی حالت کی مثال یوں سمجھیں کہ ایک مسافر کسی مقام پر ظہر سے پہلے اترتا ہے اور عصر کے وقت کے بعد تک وہیں ٹھہرا رہتا ہے، ایسی صورت میں بھی اس کے لیے نمازوں کو جمع کرنا جائز ہے۔) شیخ الاسلام امام ابن تیمیہ نے (مجموعة الرسائل والمسائل: ۲/۲۶، ۲۷) میں اس باب والی سیدنا معاذ رضی اللہ عنہ کی حدیث کے بعد کہا: جمع، تین درجات پر مشتمل ہے: (۱) جب مسافر پہلی نماز کے وقت میں سفر کر رہا ہو تو دوسری نماز کے وقت میں اتر کر دونوں نمازیں ادا کرے گا، بخاری و مسلم کی احادیث میں سیدنا انس اور سیدنا عبداللہ بن عمر رضی اللہ عنہما سے یہی صورت مروی ہے، حج کے موقع پر مزدلفہ میں نمازیں جمع کرنا اسی قبیل سے ہے۔ (۲) جب مسافر نے دوسری نماز کے وقت میں سفر کرنا ہو تو پہلی نماز کے وقت میں دونوں نمازیں جمع کر لے، عرفہ کے مقام پر جمع کرنے کا تعلق اسی صورت سے ہے، سنن میں اس صورت پر دلالت کرنے والی روایات موجود ہیں۔ (۳) رہا مسئلہ اس صورت کا کہ مسافر ایک مقام پر پہلی نماز کے وقت میں اترا اور دوسری نماز تک اس کا پڑاؤ جاری رہا، میرے علم کے مطابق اس صورت کا ذکر صرف سیدنا معاذ رضی اللہ عنہ کی حدیث میں ہے، اس حدیث کا ظاہری مفہوم یہ ہے کہ آپ صلی اللہ علیہ وسلم اپنے خیمے میں اترے، ظہر کو مؤخر کیا، پھر باہر تشریف لائے اور ظہر و عصر کو جمع کر کے ادا کیا، پھر اپنے خیمے میں داخل ہو گئے، پھر باہر تشریف لائے اور مغرب و عشا کو جمع کر کے ادا کیا، کیونکہ دخول و خروج کا تقاضا ہے کہ آپ صلی اللہ علیہ وسلم کسی منزل میں اترے ہوئے تھے، جب مسافر چل رہا ہو تو اس کے ٹھہرنے اور چلنے کو عربی زبان میں ’’نَزَلَ وَرَكِبَ‘‘ (یعنی اترے اور سوار ہوئے) کے الفاظ سے بیان کیا جاتا ہے، نہ کہ ’’دَخَلَ وَخَرَجَ‘‘ کے ساتھ۔ نبی کریم صلی اللہ علیہ وسلم کا آخری غزوہ، غزوہ تبوک تھا، اس کے بعد آپ صلی اللہ علیہ وسلم نے صرف حجة الوداع کے لیے سفر کیا اور حج کے موقع پر روایات کے مطابق صرف عرفہ اور مزدلفہ میں نمازیں جمع کر کے ادا کی گئیں منی کے مقام پر نمازیں کیسے ادا کی گئیں؟ احادیث میں صرف قصر کا ذکر ہے، جمع کا نہیں۔ اس تفصیل سے معلوم ہوتا ہے کہ آپ صلی اللہ علیہ وسلم بعض اوقات جمع کرتے اور بسا اوقات نہیں کرتے تھے، بلکہ غالب عمل جمع نہ کرنا ہے۔ اس بحث سے معلوم ہوتا ہے کہ قصر کی طرح جمع بھی سفر کی سنتوں میں سے ہے، بلکہ وہ بھی ضرورت کے مطابق ہونا چاہیے، وہ ضرورت سفر میں ہو یا حضر میں، کیونکہ آپ صلی اللہ علیہ وسلم نے اپنی امت سے تنگی اور حرج کو دور کرنے کے لیے حضر میں بھی نمازیں جمع کر کے ادا کی ہیں۔ خلاصہ کلام یہ ہوا کہ اگر مسافر ضرورت محسوس کرے تو جمع تقدیم یا جمع تاخیر کے ساتھ نمازیں جمع کر سکتا ہے۔ مثال کے طور پر اگر مسافر بوقت ظہر پڑاؤ ڈالتا ہے اور راحت و آرام، خورد و نوش اور نیند کی ضرورت محسوس کرتا ہے تو وہ ظہر کو مؤخر کر کے عصر کے ساتھ ادا کر لے۔ علی ھذا القیاس۔ جو مسافر کسی گاؤں یا شہر میں کچھ ایام کے لیے ٹھہرا ہوا ہے، تو وہ قصر نماز ادا کرے، لیکن جمع کرنے سے بچنا چاہیے، جیسا کہ وہ مسافر ہونے کے باوجود سواری پر نماز نہیں پڑھتا اور تیمم نہیں کرتا، کیونکہ اس کو ان رخصتوں کی ضرورت ہی نہیں ہے، یہی معاملہ جمع کا ہے، رہا مسئلہ قصر نماز کا تو وہ تو سفری نماز کی سنت ہے۔(صحیحہ: ۱۶۴)"}],[1051,"سیدنا ابو ہریرہ رضی اللہ عنہ سے بیان کرتے ہیں، آپ نے فرمایا: ’’ہم دنیا میں تمام امتوں کے بعد ہونے کے باوجود قیامت میں سب سے آگے رہیں گے فرق صرف یہ ہے کہ کتاب انھیں ہم سے پہلے دی گئی تھی اور ہمیں ان کے بعد دی گئی، یہی (جمعہ) ان کا بھی دن تھا جو تم پر فرض ہوا ہے لیکن ان کا اس کے بارے میں اختلاف ہوا پس اللہ تعالیٰ نے ہمیں اس کے انتخاب کی توفیق بخشی اس لیے لوگ اس میں ہمارے تابع ہو گئے، یہود دوسرے دن ہوں گے اور نصاری تیسرے دن۔‘‘","",{"k":"أخرجه البخارى: 876، 896، و مسلم: 855","e":"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جمعہ کے روز ایک ایسی گھڑی آتی ہے جس میں اگر کوئی مسلمان بندہ کھڑا نماز پڑھ رہا ہو اور کوئی چیز اللہ سے مانگے تو اللہ تعالیٰ اسے وہ چیز ضرور دیتا ہے۔‘‘(صحیح بخاری: ۹۳۵، صحیح مسلم: ۸۵۲) جناب ابو صالح سیدنا ابو ہریرہ رضی اللہ عنہ سے بیان کرتے ہیں اور وہ اللہ کے رسول صلی اللہ علیہ وسلم سے بیان کرتے ہیں کہ ’’ہم سب امتوں کے بعد آئے ہیں مگر قیامت والے دن سب سے آگے رہیں گے اور ہم سب سے پہلے جنت میں داخل ہوں گے۔‘‘(صحیح بخاری: ۸۷۶، صحیح مسلم: ۸۵۵) ہم دنیا میں آنے اور جگہ پانے کے اعتبار سے تو آخر میں ہیں لیکن روز قیامت فضل و منقبت اور عزت و شرف کے لحاظ سے سب پر فوقیت ہماری ہوگی۔ «بيد انهم» کا لفظ (غير انهم) ’’اس کے علاوہ‘‘ کے معنی میں ہے۔ بعض نے کہا: «على انهم» ’’باوجود اس کے‘‘۔ امام مزنی رحمہ اللہ کہتے ہیں: میں نے امام شافعی رحمہ اللہ کو کہتے سنا کہ لفظ (بيد) کا معنی (من اجل) ’’اس لیے‘‘ ہے۔ ابو عبید لغوی رحمہ اللہ نے کہا: اس لفظ کو (ميد انهم) بھی پڑھا گیا ہے۔ اہل عرب ’’باء‘‘ کی جگہ ’’میم‘‘ پڑھ لیتے ہیں۔ ایک حدیث میں بھی ’’باء‘‘ لفظ ’’میم‘‘ کے ساتھ مستعمل ہے: «انا افصح العرب مَيْدَ أَنِّي مِنْ قريش، وَنَشَأْتُ فِي بني سعد بن بكر» ’’میں تمام اہل عرب سے زیادہ فصیح گفتگو کرنے والا ہوں اس لیے کہ میں قبیلہ قریش سے ہوں اور میں نے بنو سعد بن بکر میں پرورش پائی ہے۔‘‘ «فهذا يومهم الذي فُرض عليهم» ’’یہی جمعہ ان کا بھی (مذہبی) دن تھا جس کی تعظیم و احترام ان پر فرض تھا‘‘ اس سے مراد یہ ہے کہ ہفتے کے سات دنوں میں سے جس دن کی تعظیم کرنا ان کے اوپر ضروری قرار دیا گیا تھا وہ یہی جمعہ کا دن تھا مگر یہود و نصاری اس دن کی فضیلت پر قائم نہ رہ سکے اور اختلاف کا شکار ہو گئے۔ یہود نے کہا: ہم ہفتہ کے دن کی تعظیم کریں گے اور اسی روز مذہبی رسومات کو پورا کریں گے اس لیے کہ اللہ تعالیٰ مخلوقات کو بنانے کے بعد اسی دن فارغ ہوا تھا۔ ہم بھی اس روز کام کاج نہیں کریں گے اور شکر گزاری میں مصروف رہیں گے۔ نصاری نے کہا: اتوار والے دن اللہ تعالیٰ نے مخلوقات بنانے کی ابتداء کی تھی لہذا یہ دن توقیر و تعظیم کا سزاوار ہے۔ اللہ تعالیٰ نے مسلمانوں کو اس سلسلہ میں ہدایت پر قائم رکھا، اب چونکہ جمعہ کا دن ہفتہ اور اتوار سے ترتیب کے لحاظ سے پہلے آتا ہے لہذا مسلمان پہلے جنت میں جائیں گے۔"}],[1052,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بہترین دن جس میں سورج طلوع ہوتا ہے، جمعے کا دن ہے، اس میں آدم پیدا کیے گئے، اسی میں ان کو جنت میں داخل کیا گیا، اسی میں ان کو زمین پر اتارا گیا، اسی دن میں قیامت قائم ہوگی اور اس دن میں ایک گھڑی ایسی ہے جسے کوئی مسلمان بندہ پالے جبکہ وہ نماز پڑھ رہا ہو اور اللہ عزوجل سے اپنی کسی ضرورت کا سوال کرے تو اللہ تعالیٰ اسے ضرور عنایت فرما دیتا ہے۔‘‘ اور آپ نے ہاتھ سے اشارہ کر کے اس گھڑی کا قلیل ہونا بیان کیا۔","",{"k":"هذا حديث صحيح: أخرجه ابوداود: 1046، والترمذى: 491، والنسائى: 3/113","e":"سیدنا عبداللہ بن سلام رضی اللہ عنہ نے کہا: مجھے معلوم ہے کہ یہ گھڑی کس وقت ہوتی ہے۔ یہ جمعہ کے دن آخری گھڑی ہوتی ہے، یہ وہی گھڑی ہے جس میں اللہ تعالیٰ نے آدم علیہ السلام کو پیدا کیا۔ اللہ سبحانہ وتعالیٰ کا ارشاد ہے:\n﴿ خَلَقَ الْإِنْسَانَ مِنْ عَجَلٍ سَأُرِيكُمْ آيَاتِي فَلَا تَسْتَعْجِلُونَ ﴾ [سورہ انبیاء: ۳۷]\n’’انسان جلد باز مخلوق ہے، میں تمھیں اپنی نشانیاں عنقریب دکھاؤں گا تم مجھ سے جلدی نہ کرو۔‘‘\n(صحیح، ابوداود: ۱۰۴۶، ترمذی: ۴۹۱، نسائی: ۳/۱۱۳)"}],[1053,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ﴿الْيَوْمُ الْمَوْعُودُ﴾ ’’وعدہ کیا ہوا دن‘‘ قیامت کا دن ہے اور ﴿الْمَشْهُودُ﴾ ’’حاضر کیا گیا‘‘ سے عرفے (نو ذوالحجہ) کا دن مراد ہے اور ﴿الشَّاهِدُ﴾ ’’حاضر ہونے والا‘‘ سے مراد جمعہ کا دن ہے۔ سورج طلوع و غروب نہیں ہوتا کسی دن میں جو جمعہ کے دن سے افضل ہو، اس دن میں ایک گھڑی ایسی ہے جسے کوئی مومن بندہ پالے اور اللہ تعالیٰ سے اپنے لیے کوئی بھلائی طلب کرے تو اللہ تعالیٰ اسے ضرور عنایت فرما دیتا ہے، یا کسی شر سے پناہ مانگے تو اللہ تعالیٰ ضرور اسے پناہ دیتا ہے۔‘‘","",{"k":"هذا حديث حسن: أخرجه الترمذى: 3339"}],[1054,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے جمعہ کے دن کا تذکرہ کیا اور فرمایا: ’’اس دن میں ایک گھڑی ایسی ہے جسے کوئی مسلمان بندہ پالے جبکہ وہ نماز پڑھ رہا ہو اور اللہ عزوجل سے اپنی کسی ضرورت کا سوال کر رہا ہو تو اللہ تعالیٰ اسے ضرور عنایت فرما دیتا ہے۔‘‘ ہاتھ کے اشارے سے آپ نے بتلایا کہ وہ گھڑی بہت تھوڑی سی ہے۔","",{"k":"أخرجه البخارى: 935، و مسلم: 852"}],[1055,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جمعہ کے دن ایک گھڑی ایسی ہے جسے کوئی مسلمان بندہ پالے جبکہ وہ نماز پڑھ رہا ہو اور اللہ عزوجل سے اپنی کسی ضرورت کا سوال کرے اللہ تعالیٰ اسے ضرور عنایت فرما دیتا ہے۔‘‘","",{"k":"أخرجه البخارى: 935، و مسلم: 852"}],[1056,"سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے انھوں نے کہا: میں کوہ طور کی طرف گیا تو جناب کعب بن احبار رحمہ اللہ کو ملا، ان سے علمی مجلس ہوئی، انھوں نے مجھے تورات سے بیان کیا جبکہ میں نے انھیں رسول اللہ صلی اللہ علیہ وسلم کی احادیث سنائیں، جو حدیثیں میں نے ان کے گوش گزار کیں ان میں سے ایک یہ حدیث مبارکہ ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’بہترین دن جس میں سورج طلوع ہوتا ہے، جمعے کا دن ہے۔ اس میں آدم پیدا کیے گئے، اسی میں ان کو زمین پر اتارا گیا، اسی دن ان کی وفات ہوئی، اسی میں ان کی توبہ قبول کی گئی اور اسی دن قیامت قائم ہوگی، جمعہ کے دن صبح ہوتے ہی تمام جانور قیامت کے ڈر سے کان لگائے ہوئے ہوتے ہیں حتی کہ سورج طلوع ہو جائے، سوائے جنوں اور انسانوں کے، اس دن میں ایک گھڑی ایسی ہے جسے کوئی مسلمان بندہ پالے جبکہ وہ نماز پڑھ رہا ہو اور اللہ عزوجل سے اپنی کسی ضرورت کا سوال کر رہا ہو تو اللہ تعالیٰ اسے ضرور عنایت فرما دیتا ہے۔‘‘ جناب کعب رحمہ اللہ نے کہا: ایسا سال میں ایک دن ہوتا ہے؟ تو میں نے جواب دیا: نہیں بلکہ ہر جمعے کو ہوتا ہے۔ تب کعب نے تورات پڑھی اور کہا: رسول اللہ صلی اللہ علیہ وسلم نے سچ فرمایا۔ سیدنا ابو ہریرہ رضی اللہ عنہ کہتے ہیں کہ میں بعد میں سیدنا عبداللہ بن سلام رضی اللہ عنہ سے ملا اور ان کو جناب کعب رحمہ اللہ کے ساتھ اپنی مجلس کا بتایا تو سیدنا عبداللہ بن سلام نے کہا: مجھے معلوم ہے کہ یہ گھڑی کس وقت ہوتی ہے۔ یہ جمعہ کے دن آخری گھڑی ہوتی ہے۔ سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا: یہ جمعہ کے دن آخری گھڑی کیسے ہو سکتی ہے؟ حالانکہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’مسلمان بندہ اسے پائے جبکہ وہ نماز پڑھ رہا ہو۔‘‘ اور اس وقت میں تو نماز نہیں پڑھی جاتی۔ سیدنا عبداللہ بن سلام رضی اللہ عنہ نے کہا: کیا رسول اللہ صلی اللہ علیہ وسلم نے نہیں فرمایا: ’’جو شخص کسی جگہ بیٹھا نماز کا انتظار کر رہا ہو تو وہ نماز ہی میں ہوتا ہے حتی کہ نماز پڑھ لے۔‘‘ میں نے کہا: ہاں، تو کہنے لگے کہ بس یہی ہے۔","",{"k":"هذا حديث صحيح: أخرجه ابوداود: 1046، والترمذى: 491، والنسائى: 3/113","e":"«إِلَّا وَهِيَ مُسِيخَةٌ» ’’تمام جانور کان لگائے ہوئے ہوتے ہیں۔‘‘ عربی لغت میں اصاخ اور اساخ کا معنی ایک ہی ہے۔"}],[1057,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’قبولیت والی گھڑی جمعہ کے دن عصر کے بعد سورج غروب ہونے سے پہلے تلاش کرو۔‘‘","",{"k":"هذا حديث حسن: أخرجه الترمذى: 489","e":"نبی صلی اللہ علیہ وسلم کے کچھ صحابہ اور دیگر آئمہ کا خیال ہے کہ یہ ساعت قبول عصر کے بعد، سورج کے غروب ہونے سے پہلے ہے۔ سیدنا عبداللہ بن عباس رضی اللہ عنہ کا یہی موقف ہے۔ نیز امام احمد اور اسحاق رحمہم اللہ نے بھی یہی کہا ہے۔ امام احمد رحمہ اللہ کہتے ہیں: اکثر و بیشتر احادیث سے یہی معلوم ہوتا ہے کہ وہ گھڑی عصر کے بعد ہے۔ زوال آفتاب کے بعد کا قول بھی ہے۔ سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ اللہ تعالیٰ کے نبی صلی اللہ علیہ وسلم نے فرمایا: ’’اسے عصر کے بعد کی آخری ساعت میں تلاش کرو۔‘‘ سیدنا ابو موسی رضی اللہ عنہ بیان کرتے ہیں کہ آپ صلی اللہ علیہ وسلم نے فرمایا: ’’یہ گھڑی امام کے منبر پر بیٹھ جانے سے لے کر نماز مکمل ہونے تک کے مابین ہے۔‘‘(صحیح مسلم: ۸۵۳)"}],[1058,"سیدنا عمرو بن عوف رضی اللہ عنہ کہتے ہیں کہ میں نے اللہ کے نبی صلی اللہ علیہ وسلم سے سنا، آپ فرما رہے تھے: ’’جمعہ کے دن ایک ایسی گھڑی ہے جس میں مسلمان بندہ جو بھی اللہ تعالیٰ سے سوال کرے اللہ تعالیٰ اسے وہ چیز عنایت فرما دیتا ہے۔‘‘ دریافت کیا گیا: اے اللہ کے رسول! یہ گھڑی کس وقت ہوتی ہے؟ آپ نے فرمایا: ’’یہ پہلی نماز کھڑے ہونے سے لے کر سلام پھیرنے تک کے درمیان ہوتی ہے۔‘‘","",{"k":"ضعيف جدا: أخرجه الترمذى: 490، و ابن ماجه: 1138","e":"کثیر راوی نے کہا: پہلی نماز سے مراد جمعہ کی نماز ہے۔ سیدنا عبداللہ بن عباس رضی اللہ عنہ سے مروی ہے کہ یہ گھڑی اذان سے لے کر امام کے نماز سے سلام پھیرنے تک کے درمیان ہے۔ سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا: یہ گھڑی امام کے منبر سے اترنے کے وقت ہوتی ہے۔ سیدنا ابو ہریرہ رضی اللہ عنہ نے کہا: جمعہ والے دن کی ساعت قبول کو تین مقامات پر تلاش کرو، فجر طلوع ہونے سے لے کر آفتاب طلوع ہونے تک کے مابین، امام کے منبر سے اترنے اور نماز کے لیے ’’اللَّهُ أَكْبَرُ‘‘ کہنے کے مابین اور عصر کے بعد سورج کے غروب ہونے سے پہلے تک، پھر انھوں نے یہ آیت تلاوت کی:\n﴿ وَاذْكُرْ رَبَّكَ فِي نَفْسِكَ تَضَرُّعًا وَخِيفَةً وَدُونَ الْجَهْرِ مِنَ الْقَوْلِ بِالْغُدُوِّ وَالْآصَالِ وَلَا تَكُنْ مِنَ الْغَافِلِينَ ﴾ [سورہ اعراف: ۲۰۵]\n’’اور اپنے رب کو یاد کیا کر اپنے دل میں عاجزی کے ساتھ اور خوف کے ساتھ اور زور کی آواز کی نسبت آہستہ آواز کے ساتھ صبح اور شام اور اہل غفلت میں سے مت ہونا۔‘‘\nنیز اللہ تعالیٰ کا فرمان ہے:\n﴿ إِذَا نُودِيَ لِلصَّلَاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ ﴾ [سورہ جمعہ: ۹]\n’’جمعہ کے دن جب نماز کی اذان دی جائے تو تم اللہ کے ذکر کی طرف دوڑ پڑو۔‘‘"}],[1059,"سیدنا ابو الجعد ضمری رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص غفلت اور سستی سے تین جمعے چھوڑ دے اللہ تعالیٰ اس کے دل پر مہر لگا دیتا ہے۔‘‘","",{"k":"هذا حديث حسن: أخرجه ابوداود: 1052، والترمذى: 500، و ابن ماجه: 1125","e":"ابو الجعد رضی اللہ عنہ صحابی ہیں، ان کا نام معروف نہیں، اس حدیث کے علاوہ ان سے اور کوئی بھی حدیث مروی نہیں ہے۔ «طبع» ’’مہر‘‘ کو کہتے ہیں۔ (طبع فلان) کا معنی ہے کہ فلاں نے مہر لگائی۔ یہ لفظ ’’با‘‘ کے فتحہ اور کسرہ دونوں طرح پڑھا جاتا ہے، مراد عزت و آبرو کا میلا ہونا ہے۔ تلوار کے عام استعمال کی وجہ سے جو زنگ چڑھ جاتا ہے اور اس کی دھار کند ہو جاتی ہے لغت میں اس کو طبع کہتے ہیں، بعد ازاں اس لفظ کا استعمال ہر بدخصلت اور قبیح صفت پر ہونے لگا۔ امام مجاہد رحمہ اللہ کہتے ہیں: ’’رَیْن‘‘ (زنگ آلود ہونا) ’’طبع‘‘ (مہر) سے کم تر مرتبہ ہے اور طبع ہلکا درجہ ہے ’’اقفال‘‘ (تالے پڑ جانا) سے اور یہ آخری درجہ سب سے شدید ہوتا ہے۔ امام بغوی رحمہ اللہ نے کہا: ارشاد باری تعالیٰ ہے:\n﴿ كَلَّا بَلْ رَانَ عَلَى قُلُوبِهِمْ مَا كَانُوا يَكْسِبُونَ ﴾ [سورہ مطففین: ۱۴]\n’’یوں نہیں بلکہ ان کے دلوں پر ان کے اعمال کی وجہ سے زنگ چڑھ گیا ہے۔‘‘\nاللہ عزوجل کا فرمان ہے:\n﴿ طَبَعَ اللَّهُ عَلَى قُلُوبِهِمْ ﴾ [سورہ توبہ: ۹۳]\n’’ان کے دلوں پر مہر خداوندی لگ چکی ہے۔‘‘\nاللہ سبحانہ وتعالیٰ کا فرمان ہے:\n﴿ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا ﴾ [سورہ محمد: ۲۴]\n’’یا ان کے دلوں پر ان کے تالے لگ گئے ہیں۔‘‘"}],[1060,"سیدنا ابن عمر اور سیدنا ابو ہریرہ رضی اللہ عنہما بیان کرتے ہیں کہ انھوں نے رسول اللہ صلی اللہ علیہ وسلم کو منبر کی سیڑھیوں پر یہ فرماتے ہوئے سنا: ’’لوگ جمعہ چھوڑنے سے باز آجائیں ورنہ اللہ تعالیٰ ضرور ان کے دلوں پر مہر لگا دے گا، پھر وہ اہل غفلت میں سے ہو جائیں گے۔‘‘","",{"k":"أخرجه مسلم: 865","e":"«عَنْ وَدْعِهِمُ الْجُمُعَاتِ» ’’جمعہ چھوڑنے سے باز آجائیں۔‘‘ شمر نے کہا: نحوی سمجھتے ہیں کہ اہل عرب اس باب کے مصدر اور ماضی کو بالکل استعمال نہیں کرتے مگر نبی صلی اللہ علیہ وسلم نے تو ودع مصدر کا استعمال فرمایا ہے اور نبی صلی اللہ علیہ وسلم کا کلام بھی فصیح ہے۔","f":"’’دل پر مہر لگ جانا بہت بڑی بدنصیبی، محرومی اور سزا ہے کہ انسان نیکی اور خیر کی توفیق سے محروم ہو جاتا ہے۔ اس لیے بندے کو فوراً اپنی اصلاح اور توبہ کرنی چاہیے۔(ع،س) امام بغوی رحمہ اللہ نے کہا: کسی عذر اور مجبوری کی بنا پر جمعہ چھوڑ دینا بالاتفاق جائز ہے۔ سیدنا سعید بن زید رضی اللہ عنہ جان کنی کے عالم میں تھے کہ سیدنا ابن عمر رضی اللہ عنہ کو بلا بھیجا، وہ جمعہ کی تیاری میں مگن تھے اور خوشبو لگا رہے تھے، اطلاع ملتے ہی تشریف لے گئے اور جمعہ نہ پڑھا۔(مسند شافعی: ۱۸۹) سیدنا ابن عباس رضی اللہ عنہ نے بارش والے دن اپنے مؤذن سے کہا: جب آپ اشهد ان محمدا رسول اللہ کہہ لیں تو حی علی الصلاة نہ کہنا بلکہ صلوا فی بیوتکم اپنے گھروں میں نماز پڑھ لو کہنا اور کہنا: بلا شبہ جمعہ فرض ہے میں نے اچھا نہیں جانا کہ تمھیں حرج میں مبتلا کروں اور تم بارش اور کیچڑ میں گرتے پڑتے آؤ۔(صحیح بخاری: ۹۰۱، صحیح مسلم: ۶۹۹) جمعہ چھوڑنے کا کفارہ بھی بیان کیا گیا ہے، سیدنا سمرہ بن جندب رضی اللہ عنہ نبی صلی اللہ علیہ وسلم سے روایت کرتے ہیں، آپ نے فرمایا: ’’جس نے کسی عذر کے بغیر جمعہ چھوڑ دیا وہ ایک دینار صدقہ کرے، اگر یہ نہ پائے تو آدھا دینار۔‘‘(ضعیف، ابوداود: ۱۰۵۳) یہ روایت بھی بیان کی گئی ہے: ’’جمعہ بغیر عذر کے چھوڑنے والا شخص ایک درہم یا آدھا درہم یا ایک صاع یا آدھا صاع گندم صدقہ کرے۔‘‘(ضعیف، ابوداود: ۱۰۵۴) سیدنا ابو ہریرہ رضی اللہ عنہ مرفوعاً بیان کرتے ہیں: ’’جس نے کسی عذر کے بغیر جمعہ چھوڑ دیا تو اس کا قیامت کے دن سے پہلے کوئی کفارہ نہیں۔‘‘ (رواہ السیوطی فی الجامع الکبیر عن الدیلمی) سیدنا ابن عباس رضی اللہ عنہ نے اللہ سبحانہ وتعالیٰ کے فرمان:\n﴿ إِذَا نُودِيَ لِلصَّلَاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ ﴾ [سورہ جمعہ: ۹]\n’’جب جمعہ کے دن نماز کی اذان دی جائے تو تم اللہ کے ذکر کی طرف دوڑ پڑو اور خرید و فروخت چھوڑ دو۔‘‘\nکے متعلق کہا: اس وقت خرید و فروخت حرام ہے۔ جناب عطاء رحمہ اللہ نے کہا: ہر قسم کا کام کاج حرام ہے۔"}],[1061,"سیدنا ابن عباس رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم کی مسجد کے بعد پہلا جمعہ بنو عبدالقیس کی مسجد میں ہوا جو ملک بحرین کے جواثاء مقام میں تھی۔","",{"k":"أخرجه البخارى: 892","e":"امام احمد بن حنبل رحمہ اللہ نے کہا: یہ حدیث اس بات کی دلیل ہے کہ دیہاتوں اور گاؤں میں جمعہ درست ہے۔ اہل علم کے مابین انعقاد جمعہ کے لیے مخصوص جگہ اور مخصوص عدد میں اختلاف پایا جاتا ہے اور یہ کہ کتنے فاصلے سے جمعہ کی ادائیگی کے لیے آیا جائے۔ جگہ کے حوالے سے تفصیل کچھ اس طرح ہے کہ کچھ لوگوں کا خیال ہے کہ وہ بستی جس میں چالیس آزاد اور مقیم باشندے ہوں تو ان پر جمعہ کی ادائیگی ضروری ہے۔ عبداللہ بن عبداللہ، عمر بن العزیز، امام شافعی، احمد اور اسحاق رحمہم اللہ کا یہی موقف ہے۔ جناب عمر بن العزیز رحمہ اللہ نے چالیس آدمیوں کی شرط کے ساتھ حاکم وقت کی موجودگی کی بھی شرط عائد کی ہے جبکہ امام شافعی رحمہ اللہ کے نزدیک والی کی شرط نہیں ہے۔ امام مالک رحمہ اللہ نے والی اور مخصوص عدد کی شرط نہیں لگائی البتہ یہ کہا ہے کہ ایسی بستی جس میں لوگوں کے گھر قریب قریب ہوں، نیز اس میں بازار اور مسجد ہو تو ان لوگوں پر جمعہ پڑھنا واجب ہے۔ سیدنا علی رضی اللہ عنہ نے کہا: جمعہ صرف بڑے شہر کی جامع مسجد میں پڑھا جا سکتا ہے۔(مصنف عبد الرزاق: ۵۱۷۵) اہل الرائے کا بھی یہی موقف ہے۔ ان حضرات کے نزدیک مصر جامع (بڑا شہر) کی شرط ہے۔ پھر ان کے ہاں چار آدمی موجود ہوں تو جمعہ ہو جاتا ہے البتہ حاکم وقت کا ہونا شرط ہے۔ امام اوزاعی رحمہ اللہ نے کہا: تین آدمی والی (حکم وقت) سمیت موجود ہوں تو جمعہ منعقد ہو جاتا ہے۔ امام ابو ثور رحمہ اللہ کہتے ہیں: دو آدمی ہوں تو جمعہ ہو جاتا ہے، جس طرح باقی نمازوں کی جماعت کے لیے دو افراد کافی ہیں۔ ربیعہ رحمہ اللہ کہتے ہیں: بارہ افراد ہوں تو جمعہ منعقد ہو جاتا ہے کیونکہ سیدنا جابر رضی اللہ عنہ اللہ تعالیٰ کے فرمان:\n﴿ وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا ﴾\n’’اور جب کوئی سودا بکتا دیکھیں یا کوئی تماشا نظر آجائے تو اس کی طرف دوڑ جاتے ہیں۔‘‘\nکے متعلق بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم جمعہ والے دن خطبہ ارشاد فرما رہے تھے کہ اتنے میں شام سے ایک تجارتی قافلہ غلہ لے کر آگیا تو سارے لوگ اس کی طرف نکل گئے یہاں تک کہ مسجد میں صرف بارہ افراد رہ گئے اور اس موقع پر یہ آیت کریمہ نازل ہوئی۔(صحیح بخاری: ۹۳۶، صحیح مسلم: ۸۶۳) اس واقعہ میں اس بات کی کوئی دلیل موجود نہیں کہ جمعہ کے انعقاد کے لیے اس عدد (۱۲) کا پایا جانا شرط ہے۔ جناب عبد الرحمن بن کعب بن مالک اپنے والد کعب سے بیان کرتے ہیں کہ جمعہ کے روز جب وہ جمعہ کی اذان سنتے تو اسعد بن زرارہ رضی اللہ عنہ کے لیے رحمت کی دعا کرتے۔ میں نے ان سے کہا: آپ جب اذان سنتے ہیں تو اسعد بن زرارہ رضی اللہ عنہ کے لیے رحمت کی دعا کرتے ہیں اس کی کیا وجہ ہے؟ انھوں نے کہا: اس لیے کہ حرہ بنی بیاضہ میں ’’حزم النبیت‘‘ کے اندر انھوں نے ہی سب سے پہلے ہمیں جمعہ پڑھایا تھا۔ ایک نقیع میں جسے ’’نقیع الخصمات‘‘ کہا جاتا تھا (یعنی نشیبی جگہ جہاں پانی جمع ہو جاتا تھا)۔ میں نے ان سے پوچھا: آپ لوگوں کی تعداد کتنی تھی؟ انھوں نے کہا: چالیس افراد۔(حسن، ابوداود: ۱۰۶۹) ابو سلیمان خطابی رحمہ اللہ نے کہا: نقیع اس نشیبی جگہ کو کہتے ہیں جہاں کچھ عرصہ پانی رکا رہے اور جب پانی خشک ہو تو گھاس اُگ آئے۔ «بنو بیاضة» انصار کی ایک شاخ ہے۔ «حر» سنگلاخ اور گرم زمین کو کہتے ہیں جو مدینے سے ایک میل کے فاصلے پر تھی۔","f":"ان حضرات کا چالیس کی تعداد میں ہونا ایک اتفاقی عدد اور خبر ہے ورنہ صحت جمعہ کے لیے افراد کی تعداد متعین ہونے کی بابت کوئی روایت صحیح نہیں ہے۔ راجح بات یہی ہے کہ نماز جمعہ کی جماعت کے لیے بھی کم از کم دو افراد ہی کافی ہیں۔(ع،س) کتنی مسافت سے جمعہ پڑھنے کے لیے حاضر ہونا ضروری ہے، اگر وہاں جمعہ نہ ہو رہا ہو؟ ام المؤمنین سیدہ عائشہ رضی اللہ عنہا کہتی ہیں: لوگ اپنے ڈیروں سے اور بالائے مدینہ (عوالی) سے جمعہ کے لیے آیا کرتے تھے۔(صحیح بخاری: ۹۰۲) سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’اس شخص پر جمعہ پڑھنا ضروری ہے جو رات کو واپس اپنے بال بچوں میں لوٹ سکے۔‘‘(ضعیف جدا، ترمذی معلقا بعد الحدیث: ۵۰۱) بعض اہل علم کا موقف یہ ہے۔ سیدنا انس رضی اللہ عنہ کے بارے میں مروی ہے کہ کبھی تو وہ اپنے محل میں جمعہ منعقد کرتے اور کبھی نہ کرتے اور ان کا محل دو فرخ کے فاصلے پر تھا۔ ابراہیم نے کہا: دو فرخ کی مسافت اور دوری سے جمعہ پڑھنے کے لیے آنا چاہیے۔ بعض نے کہا: ان لوگوں پر جمعہ پڑھنا واجب ہے جن کو جمعہ کی اذان سنائی دیتی ہو۔ امام شافعی، احمد اور اسحاق رحمہم اللہ کا موقف یہی ہے۔ سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ وہ نبی صلی اللہ علیہ وسلم سے بیان کرتے ہیں: ’’ہر اس شخص پر جمعہ ہے جو اذان سنے۔‘‘(ضعیف، ابوداود: ۱۰۵۶) امام بغوی رحمہ اللہ نے کہا: جب کوئی شخص ایسی بستی میں رہائش پذیر ہو جس میں جمعہ منعقد ہوتا ہو تو ایسے شخص کے لیے جمعہ کی اذان سننے کی کوئی شرط نہیں (بلکہ اس پر جمعہ کی ادائیگی فرض ہے)۔ جناب عطاء رحمہ اللہ نے کہا: جب آپ ایسی بستی میں اقامت گزیں ہوں جس میں جمعہ منعقد ہوتا ہو تو آپ پر لازم ہے کہ جمعہ ادا کریں آپ نے اذان سنی ہو یا نہ۔ امام محمد رحمہ اللہ نے کہا: اگر جمعہ اور عید اکٹھے آجائیں تو زوال سے پہلے عید پڑھی جائے گی اور زوال کے بعد اکثر اہل علم کے نزدیک جمعہ پڑھنا ضروری ہے۔ سیدنا ابو ہریرہ رضی اللہ عنہ سے روایت کرتے ہیں کہ آپ نے فرمایا: ’’تمھارے اس دن دو عیدیں جمع ہو گئی ہیں، تو جو چاہے اس کے لیے یہ (نماز عید) جمعہ کے بدلے کافی ہے اور ہم جمعہ پڑھیں گے۔‘‘(صحیح، ابوداود: ۱۰۷۳) جناب عطاء بن ابی رباح رحمہ اللہ نے بیان کیا کہ سیدنا ابن زبیر رضی اللہ عنہ کے دور خلافت میں جمعہ اور عید فطر ایک ہی دن آگئے، تو انھوں نے ان دونوں کو جمع کر دیا اور پہلے پہر دو رکعتیں پڑھائیں اور ان پر کچھ اضافہ نہ کیا حتی کہ عصر پڑھی۔(صحیح، ابوداود: ۱۰۷۲) مروی ہے کہ ابن عباس رضی اللہ عنہ کو جب ابن زبیر رضی اللہ عنہ کے مذکورہ صدر عمل کی بابت علم ہوا تو کہا: انھوں نے سنت پر عمل کیا ہے۔(صحیح، ابوداود: ۱۰۷۱) ابراہیم نخعی رحمہ اللہ نے کہا: جب دو عیدیں ایک دن میں جمع ہو جائیں (جمعہ اور عید) تو ان دونوں میں سے ایک کا پڑھ لینا کافی ہے۔ ابو سلیمان خطابی رحمہ اللہ کہتے ہیں: سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی حدیث کی سند میں کلام ہے۔ صحیح مان لینے کی صورت میں اس حدیث کا معنی یہ ہوگا کہ جو چاہے اس کے لیے نماز عید کا پڑھنا جمعہ کے بدلے کافی ہے۔ یعنی اسے جمعہ کی رخصت ہے لیکن وہ ظہر کی نماز ضرور پڑھے گا۔ نماز ظہر اس سے ساقط نہیں ہوگی، لہذا ابن عمر رضی اللہ عنہ کا طرز عمل (رخصت کو سب کے لیے عام سمجھنا) میرے نزدیک درست نہیں۔ البتہ ان علماء کے نزدیک ٹھیک ہوگا جو زوال سے پہلے جمعہ کی ادائیگی جائز سمجھتے ہیں، ایسا سیدنا عبداللہ بن مسعود رضی اللہ عنہ سے مروی ہے۔ جناب عطاء نے کہا: ہر عید چاشت کے وقت پڑھی جا سکتی ہے، جمعہ، عید فطر اور عید حی۔ امام احمد بن حنبل رحمہ اللہ سے سوال کیا گیا کہ کیا جمعہ زوال سے پہلے پڑھا جائے یا بعد میں؟ تو انھوں نے جواب دیا: اگر میں زوال سے قبل پڑھ لوں تو دوبارہ نہیں پڑھوں گا، اسحاق نے بھی یہی کہا ہے۔ اس قول کو سامنے رکھتے ہوئے کہا جا سکتا ہے کہ سیدنا ابن زبیر رضی اللہ عنہ نے ممکن ہے دو رکعتیں جمعہ کی نیت سے پڑھی ہوں اور عید کو جمعہ کی فرع سمجھ لیا ہو، یہ امام خطابی رحمہ اللہ کا تبصرہ ہے۔ بظاہر یہ معلوم ہو رہا ہے کہ سیدنا ابن زبیر رضی اللہ عنہ نے نماز عید کے بعد ظہر کی نماز نہیں پڑھی، صرف عصر کی نماز پڑھی۔ لیکن صاحب سبل السلام نے کہا ہے کہ یہ روایت ظہر کے نہ پڑھنے میں نص قاطع نہیں ہے کیونکہ یہ ممکن ہے کہ انھوں نے نماز ظہر گھر ہی میں ادا کر لی ہو۔ اس کی مزید تائید امام عطاء رحمہ اللہ کے اس قول سے بھی ہوتی ہے کہ: انہم صلوا وحدانا ’’لوگوں نے اکیلے نماز ادا کر لی۔‘‘ اور اس کے برخلاف بالاتفاق جمعہ جماعت کے ساتھ ہی درست ہے، لہذا انھوں نے جمعہ نہیں پڑھا بلکہ صرف نماز ظہر ہی اکیلے ادا کر لی۔ بہر حال عید کے دن جمعہ کی رخصت ہے نماز ظہر کی نہیں لیکن جمعہ پڑھنا مستحب ہے۔ افضل یہ ہے کہ امام استحباب پر عمل کرے نہ کہ رخصت پر تا کہ جمعہ پڑھنے والوں کو کسی قسم کی تکلیف یا پریشانی نہ ہو۔ واللہ اعلم (ع،س) قارئین کی سہولت کے لیے اس موضوع پر درج ذیل پیش کی جاتی ہے: جمعہ کی اہمیت کے حوالے سے دو احادیث تحریر کی جاتی ہیں: سیدنا عبداللہ بن مسعود رضی اللہ عنہ کہتے ہیں: رسول اللہ صلی اللہ علیہ وسلم نے جمعہ سے پیچھے رہ جانے والے لوگوں کے بارے میں فرمایا: «لَقَدْ هَمَمْتُ أَنْ آمُرَ رَجُلًا يُصَلِّي بِالنَّاسِ، ثُمَّ أُحَرِّقَ عَلَى رِجَالٍ يَتَخَلَّفُونَ عَنِ الْجُمُعَةِ بُيُوتَهُمْ» ...... ’’میں نے یہ ارادہ کیا ہے کہ کسی آدمی کو حکم دوں کہ وہ لوگوں کو نماز پڑھائے اور خود جمعہ سے پیچھے رہ جانے والے لوگوں کے گھر جلانے کے لیے (چلا جاؤں)۔‘‘(مسلم: ۶۵۲) سیدنا ابو الجعد ضمری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «مَنْ تَرَكَ ثَلَاثَ جُمَعٍ تَهَاوُنًا بِهَا طَبَعَ اللَّهُ عَلَى قَلْبِهِ» ...... ’’جو شخص غفلت اور سستی سے تین جمعے چھوڑ دے، اللہ تعالی اس کے دل پر مہر لگا دیتا ہے۔‘‘(ابوداود: ۱۰۵۲، ترمذی: ۵۰۰، نسائی: ۱۳۷۰، ابن ماجہ: ۱۱۲۵) ہمیں اس ضمن میں سب سے زیادہ تعجب احناف پر ہوتا ہے، جو فتووں کی حد تک تو دیہاتوں اور قصبوں میں نماز جمعہ اور نماز عید کے قائل نہیں ہیں، لیکن عملی طور پر اکثر و بیشتر گاؤں میں نماز جمعہ کا اور تقریباً ہر گاؤں میں نماز عید کا بھر پور اہتمام کرتے ہیں، بلکہ بعض بستیوں میں احناف کی دو دو تین تین مساجد میں نماز جمعہ ادا کی جاتی ہے۔ ایک ’’حنفی مقلد عالم‘‘ اس گاؤں میں بستیوں میں نماز جمعہ اور نماز عید کی ادائیگی کی زبردست مخالفت کر رہا ہوتا ہے، جبکہ دوسری بستی میں نماز جمعہ پڑھانے والا وہ خود ہوتا ہے۔ پھر عوام الناس کو تسلی دلانے اور اپنے آپ کو تنکے کا سہارا دینے کے لیے یہ کہہ دیا جاتا ہے کہ جہاں نماز جمعہ کی ادائیگی شروع کر دی جائے وہاں اس کو چھوڑا نہیں جا سکتا۔ ارے! کچھ تو غور کر لیا ہوتا کہ جہاں جمعہ کی نماز ادا کرنا صحیح ہی نہیں ہے، وہاں اس کی ابتدا کیسے ہو گئی؟! بہر حال اب ہم شرعی نصوص کا جائزہ لیتے ہیں، آخر میں حنفی مسلک کی وضاحت کی جائے گی۔ ہر عاقل اور بالغ مسلمان پر نماز جمعہ ادا کرنا فرض ہے۔ (۱) ارشاد باری تعالیٰ ہے: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلَاةِ مِنْ يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَى ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ ذَلِكُمْ خَيْرٌ لَكُمْ إِنْ كُنْتُمْ تَعْلَمُونَ﴾ (سورۂ جمعہ: ۹) ...... ’’اے ایمان والو! جب جمعہ کے دن نماز کے لیے اذان دی جائے تو اللہ تعالی کی یاد کی طرف آؤ اور لین دین چھوڑ دو، یہ تمھارے لیے بہتر ہے، اگر تم جانتے ہو۔‘‘ یہ آیت عام ہے، اس میں ہر صاحب ایمان کو نماز جمعہ ادا کرنے کا حکم دیا گیا ہے، صرف ان لوگوں کو مستثنی کیا جائے گا جن کو شریعت نے رخصت دی ہے، جیسے غلام، عورت، بچہ اور مریض۔ (۲) سیدہ حفصہ رضی اللہ عنہا سے مروی ہے کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: «رَوَاحُ الْجُمُعَةِ وَاجِبٌ عَلَى كُلِّ مُحْتَلِمٍ» ...... ’’جمعہ میں حاضر ہونا ہر بالغ پر واجب ہے۔‘‘(ابوداود: ۳۴۲، نسائی: ۱۳۷۲) یہ حدیث مبارکہ بھی عام ہے اور ہر مسلمان کو شامل ہے، وہ دیہاتی ہو یا شہری۔ (۳) سیدنا طارق بن شہاب رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: «الْجُمُعَةُ حَقٌّ وَاجِبٌ عَلَى كُلِّ مُسْلِمٍ فِي جَمَاعَةٍ إِلَّا أَرْبَعَةً: عَبْدٍ مَمْلُوكٍ أَوِ امْرَأَةٍ أَوْ صَبِيٍّ أَوْ مَرِيضٍ» ...... ’’ہر مسلمان پر نماز جمعہ جماعت کے ساتھ واجب ہے، سوائے ان چار افراد کے: غلام، عورت، بچہ اور مریض۔‘‘(ابوداود: ۱۰۶۷، مستدرک حاکم: ۱۰۶۲) رسول اللہ صلی اللہ علیہ وسلم نے اس حدیث میں ہر مسلمان پر جمعہ واجب قرار دیا ہے اور صرف چار افراد کو مسجد میں نہ آنے کی رخصت دی ہے۔ ذہن نشین رہنا چاہیے کہ سیدنا طارق بن شہاب رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا تھا البتہ یہ بات درست ہے کہ ان کا آپ صلی اللہ علیہ وسلم سے سماع نہیں ہے، لیکن راجح قول کے مطابق صحابی کی مرسل حجت ہوتی ہے۔ (۴) ایک دلچسپ واقعہ یہ ہے کہ جب سیدنا کعب بن مالک رضی اللہ عنہ جمعہ کے روز اذان سنتے تو سیدنا اسعد بن زرارہ رضی اللہ عنہ کے لیے رحم کی دعا کرتے۔ ان کے بیٹے نے ان سے سبب پوچھا کہ جب بھی آپ اذان سنتے ہیں تو اسعد بن زرارہ کے لیے رحم کی دعا کرتے ہیں؟ انھوں نے جواباً کہا: «لِأَنَّهُ أَوَّلُ مَنْ جَمَعَ بِنَا فِي هَزْمِ النَّبِيتِ مِنْ حَرَّةِ بَنِي بَيَاضَةَ فِي نَقِيعٍ يُقَالُ لَهُ نَقِيعُ الْخَضِمَاتِ. قُلْتُ: كَمْ أَنْتُمْ يَوْمَئِذٍ؟ قَالَ: أَرْبَعُونَ۔» ...... ’’وہ (اسعد) پہلا شخص ہے، جس نے مقام نقیع (نقیع الخصمات) میں واقع بنو بیاضہ کی زمین ’’ہزم نبیت‘‘ میں ہمیں پہلا جمعہ پڑھایا تھا۔‘‘ میں نے کہا: (ابو جان!) آپ اس وقت کتنے لوگ تھے؟ انھوں نے بتایا: چالیس آدمی تھے۔(ابوداود: ۱۰۶۹، ابن ماجہ: ۱۰۸۲) ابن ماجہ کی روایت کے الفاظ یہ ہیں اور قابل غور ہیں: «أَيُّ بُنَيَّ كَانَ أَوَّلَ مَنْ صَلَّى بِنَا صَلَاةَ الْجُمُعَةِ قَبْلَ مَقْدَمِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مَكَّةَ فِي نَقِيعِ الْخَضِمَاتِ۔......» ’’اے میرے بیٹا! وہ (اسعد) پہلا شخص ہے، جس نے نبی کریم صلی اللہ علیہ وسلم کے مکہ سے (مدینہ میں) آنے سے پہلے ہم کو ’’نقیع الخصمات‘‘ میں نماز جمعہ پڑھائی تھی......‘‘ یہ ’’حرہ بنی بیاضہ‘‘ مدینہ منورہ سے ایک میل کے فاصلے پر ایک گاؤں تھا۔(التلخیص الحبیر: ۲/۵۷) یہ چالیس آدمی اتفاقی طور پر تھے، اس لیے یہ استدلال نہیں کیا جا سکتا ہے کہ کم از کم اتنی تعداد کا ہونا ضروری ہے، جبکہ صحیح بخاری اور صحیح مسلم کی روایت کے مطابق آپ صلی اللہ علیہ وسلم خطبہ جمعہ ارشاد فرما رہے تھے، شام سے ایک تجارتی قافلے کی آمد پر لوگ اس کی طرف چلے گئے اور آپ صلی اللہ علیہ وسلم کا خطبہ سننے والے صرف بارہ آدمی بچ گئے تھے۔ اس وقت یہ آیت نازل ہوئی تھی: ﴿وَإِذَا رَأَوْا تِجَارَةً أَوْ لَهْوًا انْفَضُّوا إِلَيْهَا وَتَرَكُوكَ قَائِمًا﴾ (سورۂ جمعہ: ۱۱) خطابی نے کہا: اس حدیث کی فقہ یہ ہے کہ شہروں کی طرح بستیوں میں بھی جمعہ جائز ہے کیونکہ یہ حرہ بنو بیاضہ مدینہ سے ایک میل کے فاصلے پر تھا۔(عون المعبود: ۱/۵۴۱) اس حدیث پر امام ابوداود نے ’’باب الجمعة فی القری‘‘ (بستیوں میں جمعہ کی ادائیگی کا بیان) اور امام ابن ماجہ نے ’’باب فی فرض الجمعة‘‘ (جمعہ کے فرض ہونے کے بیان) کی سرخیاں ثبت کی ہیں۔ امام شوکانی نے کہا: نبی کریم صلی اللہ علیہ وسلم پر مکہ ہی میں جمعہ فرض ہو گیا تھا، جیسا کہ امام طبرانی نے سیدنا ابن عباس رضی اللہ عنہ کی روایت میں بیان کیا ہے، لیکن کافروں کی وجہ سے اس کی ادائیگی ممکن نہ تھی۔ جب صحابہ نے مدینہ منورہ کی طرف ہجرت کی تو آپ صلی اللہ علیہ وسلم نے ان کی طرف یہ فرمان لکھا کہ وہ جمعہ ادا کیا کریں، سو انھوں نے ایسے ہی کیا اور اتفاقی طور پر وہاں چالیس آدمی موجود تھے، اس کا یہ مطلب نہیں کہ چالیس سے کم افراد ہوں تو جمعہ نہیں ہوتا۔(نیل الاوطار: ۳/۲۷۴) (۵) سیدنا عبداللہ بن عباس رضی اللہ عنہ کہتے ہیں: «أَوَّلُ جُمُعَةٍ جُمِعَتْ فِي مَسْجِدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَسْجِدِ عَبْدِ الْقَيْسِ بِجُوَاثَى، يَعْنِي قَرْيَةً مِنَ الْبَحْرَيْنِ۔» ...... ’’رسول اللہ صلی اللہ علیہ وسلم کی مسجد میں جو جمعہ ادا کیا گیا، اس کے بعد پہلا جمعہ بحرین کے ایک گاؤں جواثی میں عبدالقیس کی مسجد میں ادا کیا گیا۔‘‘(صحیح بخاری: ۸۹۲، ۴۳۷۱، ابوداود: ۱۰۶۸) امام بخاری رحمہ اللہ نے اس حدیث پر ’’باب الجمعة فی القری والمدن‘‘ (بستیوں اور شہروں میں جمعہ کی ادائیگی کا بیان) کی سرخی ثبت کی ہے۔ ابو عمر عامر فاروق سعدی نے سنن ابوداود کے فوائد (۱/۷۶۱) میں کہا: جواثی کی مسجد کے آثار آج بھی موجود ہیں، چھوٹی سی جگہ ہے اور صرف دو صفوں کا دالان ہے۔ (۶) سیدہ عائشہ رضی اللہ عنہا کہتی ہیں: «كَانَ النَّاسُ يَتَنَاوَبُونَ الْجُمُعَةَ مِنْ مَنَازِلِهِمْ وَ مِنَ الْعَوَالِيِ۔» ...... ’’لوگ اپنے ڈیروں سے اور بالائے مدینہ (عوالی) سے جمعہ کے لیے آیا کرتے تھے۔‘‘(صحیح بخاری: ۹۰۲، صحیح مسلم: ۸۴۷) ’’عوالی‘‘ کی آبادیاں مدینہ منورہ سے تین سے آٹھ میل کی مسافت تک تھیں۔ ’’یتنابون‘‘ کے معانی: بار بار آنا، آمد و رفت رکھنا، کوئی کام باری باری کرنا۔ متن کا ترجمہ اول الذکر معانی کو دیکھ کر کیا گیا ہے، جس میں اشکال نہیں پایا جاتا۔ ایک روایت میں ’’یتناوبون‘‘ کے الفاظ ہیں، اس کے معانی یہ ہیں: کوئی کام بار بار کرنا، آپس میں کوئی چیز باری باری لینا، کام باری باری کرنا۔ اگر ان الفاظ کے مؤخر الذکر معانی کو مد نظر رکھا جائے تو ایسے معلوم ہوتا ہے کہ عوالی کے سارے لوگ نہیں آتے تھے، درج ذیل کلام ملاحظہ فرمائیں: شارح ابوداود علامہ عظیم آبادی لکھتے ہیں: اگر کوئی آدمی اس حدیث سے یہ استدلال کرے کہ عوالی والوں پر جمعہ فرض نہیں تھا، بصورت دیگر وہ سب آتے اور باری باری نہ آتے۔ میں یوں جواب دوں گا: سیدہ عائشہ رضی اللہ عنہا کے قول کا یہ مطلب نہیں ہے کہ بعض لوگ جمعہ ادا کرنے کے لیے مسجد نبوی آجاتے اور بعض اپنے گھروں میں ہی رہتے۔ بلکہ اس کا مفہوم یہ ہے کہ جو لوگ بروز جمعہ اپنے گھروں پر ہوتے وہ یہ نماز ادا کرنے کے لیے مدینہ آتے تھے، کیونکہ ان میں ایسے افراد بھی ہوتے جو سفر یا کسی کام کی وجہ سے گھر پر نہ ہوتے تھے اور کوئی معذور ہوتا تھا، اس لیے وہ سارے کے سارے حاضر نہیں ہو سکتے تھے، البتہ جب وہ گھر پہنچ جاتے یا عذر زائل ہو جاتا تو وہ مسجد نبوی میں آجاتے تھے۔ پس ان کا باری باری آنا اس بنا پر تھا، نہ کہ جمعہ کی پروا نہ کرنے کی بنا پر۔(عون المعبود: ۱/۵۳۴) دوسری بات یہ ہے کہ محض احتمال کو سامنے رکھ کر واضح نصوص کو رد نہیں کیا جا سکتا۔ (۷) سیدنا عبداللہ بن عمر رضی اللہ عنہ کہتے ہیں: «إِنَّ أَهْلَ قُبَاءَ كَانُوا يُجَمِّعُونَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْجُمُعَةِ۔» ...... ’’قبا بستی والے لوگ جمعہ والے دن رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعہ ادا کرتے تھے۔(ابن ماجہ: ۱۱۲۴، حسنہ بعضہم و ضعفہ بعضہم ولہ شواہد) قبا، مدینہ سے دو میل کے فاصلے پر تھی۔ حافظ ابن حجر نے صحابہ کے اقوال نقل کرتے ہوئے کہا: «وَعَنْ عُمَرَ أَنَّهُ كَتَبَ إِلَى أَهْلِ الْبَحْرَيْنِ أَنْ جَمِّعُوا حَيْثُمَا كُنْتُمْ وَهَذَا يَشْمَلُ الْمُدُنَ وَالْقُرَى أخرجه بن أَبِي شَيْبَةَ أَيْضًا مِنْ طَرِيقِ أَبِي رَافِعٍ عَنْ أَبِي هُرَيْرَةَ عَنْ عُمَرَ وَصَحَّحَهُ بن خُزَيْمَةَ وَرَوَى الْبَيْهَقِيُّ مِنْ طَرِيقِ الْوَلِيدِ بْنِ مُسْلِمٍ سَأَلْتُ اللَّيْثَ بْنَ سَعْدٍ فَقَالَ كُلُّ مَدِينَةٍ أَوْ قَرْيَةٍ فِيهَا جَمَاعَةٌ أُمِرُوا بِالْجُمُعَةِ فَإِنَّ أَهْلَ مِصْرَ وَسَوَاحِلَهَا كَانُوا يُجَمِّعُونَ الْجُمُعَةَ عَلَى عَهْدِ عُمَرَ وَعُثْمَانَ بِأَمْرِهِمَا وَفِيهِمَا رِجَالٌ مِنَ الصَّحَابَةِ وَعِنْدَ عَبْدِ الرَّزَّاقِ بِإِسْنَادٍ صَحِيحٍ عَنْ بْنِ عُمَرَ أَنَّهُ كَانَ يَرَى أَهْلَ الْمِيَاهِ بَيْنَ مَكَّةَ وَالْمَدِينَةِ يُجَمِّعُونَ فَلَا يَعِيبُ عَلَيْهِمْ فَلَمَّا اخْتَلَفَ الصَّحَابَةُ وَجَبَ الرُّجُوعُ إِلَى الْمَرْفُوعِ» ’’سیدنا عمر رضی اللہ عنہ نے اہل بحرین کی طرف خط لکھا کہ: ’’تم جہاں کہیں بھی ہو، جمعہ پڑھا کرو۔‘‘ یہ حکم دیہاتیوں اور شہریوں دونوں کو شامل ہے۔ اسی طرح ابن ابی شیبہ نے ابو رافع کی سند سے سیدنا ابو ہریرہ اور سیدنا عمر رضی اللہ عنہما سے روایت کیا اور امام ابن خزیمہ نے اسے صحیح کہا۔ بیہقی نے ولید بن مسلم کی سند سے روایت کی ہے کہ جب اس نے امام لیث بن سعد سے سوال کیا تو انھوں نے کہا: ہر وہ شہر یا گاؤں جس میں جماعت ہو، انھیں جمعہ ادا کرنے کا حکم دیا گیا ہے۔ یقیناً سیدنا عمر رضی اللہ عنہ اور سیدنا عثمان رضی اللہ عنہ کے حکم سے مصر اور ساحل سمندر پر رہنے والے لوگ جمعہ پڑھتے تھے اور ان میں صحابہ کرام بھی تھے۔ عبد الرزاق کے ہاں صحیح سند کے ساتھ سیدنا عبداللہ بن عمر رضی اللہ عنہ سے روایت ہے کہ وہ مکہ اور مدینہ کے درمیان اہل میاہ کو دیکھتے کہ وہ جمعہ ادا کرتے تھے اور ابن عمر رضی اللہ عنہ ان پر عیب نہیں لگاتے تھے۔ چنانچہ جب صحابہ کرام میں اختلاف ہو گیا تو مرفوع حدیث کی طرف رجوع کرنا واجب ہو گیا۔(فتح الباری: ۳/۳۸۰) امام ابن حزم نے کہا: ’’دیہات میں جمعہ سے روکنے والوں کے خلاف سب سے بڑی دلیل یہ ہے کہ جب رسول اللہ صلی اللہ علیہ وسلم مدینہ منورہ میں تشریف لائے تو مدینہ اس وقت چھوٹی چھوٹی بستیوں میں تقسیم تھا۔ بنو مالک بن نجار کے گھر، اموال اور کھجوروں کے باغات علیحدہ تھے، اسی طرح بنو عدی بن نجار اور بنو عبد الاشہل جدا جدا زندگی گزار رہے تھے۔ نبی کریم صلی اللہ علیہ وسلم نے بنو مالک بن نجار میں اپنی مسجد کی بنیاد رکھی اور جمعہ ایسی بستی میں ادا کیا جو بڑی نہ تھی اور نہ وہاں کوئی شہر تھا۔ پس اس شخص کا دعوی باطل ہو گیا جس نے کہا کہ شہر کے علاوہ جمعہ نہیں ہے اور یہ ایک ایسا معاملہ ہے جس سے کوئی شخص جاہل نہیں ہے، نہ ایمان والا نہ کافر۔‘‘(محلی ابن حزم: ۵/۵۴) آج کل نبی کریم صلی اللہ علیہ وسلم کی مسجد کے محراب اور قبر مبارک والے حجرے اور اصحاب صفہ کے چبوترے سے یہ اندازہ لگایا جا سکتا ہے کہ مسجد نبوی کتنی بڑی تھی۔ غزوہ بدر میں شرکت کرنے والے کل مہاجرین و انصار کی تعداد (۳۱۳) تھی، ان میں اصحاب صفہ اور انصاریوں کے گھروں میں رہنے بے گھر مہاجر بھی شامل تھے، اس تعداد سے ان کے گھروں کی تعداد کا اندازہ لگا کر مدینہ منورہ کے بارے میں یہ فیصلہ کرنا آسان ہو جاتا ہے کہ وہ کتنا بڑا شہر تھا؟ کیا ’’مصر جامع‘‘ کی شرط لگانے والے سوچتے نہیں ہیں؟ شارح ابوداود علامہ عظیم آبادی رحمہ اللہ نے خلاصہ کلام پیش کرتے ہوئے کہا: سلف کے ان آثار سے معلوم ہوتا ہے کہ بستیوں اور دیہاتوں میں جمعہ ادا کرنا صحیح ہے، اور اس ضمن میں قرآن مجید کی آیت ﴿إِذَا نُودِيَ لِلصَّلَاةِ﴾ کا عام حکم ہی کافی ہے، کسی آیت یا سنت صحیحہ سے اس کا تخصیص ثابت ہے نہ تخصیص اور رسول اللہ صلی اللہ علیہ وسلم سے اس حقیقت کے برعکس کوئی چیز ثابت نہیں ہے۔(عون المعبود: ۱/۵۴۳) عام طور پر احناف کی طرف سے یہ دلیل پیش کی جاتی ہے: «لَا جُمُعَةَ وَلَا تَشْرِيقَ إِلَّا فِي مِصْرٍ جَامِعٍ» ...... ’’نماز جمعہ اور نماز عید نہیں ہے، مگر بڑے شہر میں۔‘‘ لیکن قطعی طور پر یہ رسول اللہ صلی اللہ علیہ وسلم سے باسند صحیح ثابت نہیں ہے۔ امام بیہقی نے کہا: «لَا يُرْوَى عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ذَلِكَ شَيْءٌ۔» ...... ’’اس بارے میں نبی کریم صلی اللہ علیہ وسلم سے کوئی (حدیث) مروی نہیں ہے۔‘‘(نصب الرایہ: ۲/۱۹۵، الدرایہ: ۱/۲۱۴) یہ سیدنا علی رضی اللہ عنہ پر موقوف ہے اور بالاتفاق موقوف روایت مرفوع روایت کا مقابلہ نہیں کر سکتی۔ اس کی تائید اس سے بھی ہوتی ہے کہ خود احناف اس قول پر عمل نہیں کرتے اور بے شمار بستیوں میں نماز جمعہ اور ہر بستی میں نماز عید کا اہتمام کرتے ہیں۔ ان لوگوں نے اس قول کو ان چند بستیوں کے ساتھ خاص کر رکھا ہے جہاں کوئی ذاتی یا امانیت کا مسئلہ پایا جاتا ہو۔ دوسری بات یہ ہے کہ سیدنا عمر، سیدنا عثمان، سیدنا عبداللہ بن عمر اور سیدنا ابو ہریرہ رضی اللہ عنہم بستیوں میں نماز جمعہ کے قائل ہیں اور یہ مسلک آیت اور احادیث سے زیادہ موافقت بھی رکھتا ہے، اس لیے اس کو ترجیح دینی چاہیے۔ فقہ حنفی اور نماز جمعہ: قرآن و حدیث کی روشنی میں مسئلہ کی وضاحت ہو چکی ہے، اب ہم قارئین کے فائدے کے لیے فقہ حنفی کی معروف کتاب ’’الہدایہ‘‘ کا اقتباس اور اس کے حاشی جناب محمد عبد الحی لکھنوی حنفی کا کلام پیش کرتے ہیں، تاکہ حقائق واضح ہو جائیں، آخر میں ان کا خلاصہ کلام پیش کریں گے۔ ’’مصر جامع‘‘ سے مراد بڑا شہر اور ’’مصر‘‘ سے مراد شہر ہے، مزید وضاحت متن اور حاشیہ میں موجود ہوگی۔ صاحب ہدایہ جناب ابو الحسن علی بن ابو بکر مرغینانی لکھتے ہیں: نماز جمعہ صحیح نہیں ہے، مگر ’’مصر جامع‘‘ میں یا اس ’’مصر‘‘ کی خالی جگہ میں اور یہ نماز بستیوں میں جائز نہیں ہے، کیونکہ آپ صلی اللہ علیہ وسلم نے فرمایا: «لَا جُمُعَةَ وَلَا تَشْرِيقَ وَلَا فِطْرَ وَلَا أَضْحَى إِلَّا فِي مِصْرٍ جَامِعٍ» ...... ’’نماز جمعہ ہے، نہ نماز عید ہے، یعنی عید الفطر اور عید الاضحی، مگر مصر جامع میں۔‘‘ ’’مصر جامع‘‘ ہر اس جگہ کو کہتے ہیں جہاں امیر اور قاضی ہو جو (شرعی) احکام اور حدود کا نفاذ کرتا ہو، یہ ابو یوسف کا قول ہے اور محمد کا قول یہ ہے کہ جب لوگ سب سے بڑی مسجد میں جمع ہوں لیکن وہ تنگ پڑ جائے (تو اسے ’’مصر جامع‘‘ کہیں گے)، پہلا قول کرخی نے اختیار کیا ہے اور وہی ظاہر ہے اور دوسرا قول شیخ کی ترجیح ہے...... منی میں جمعہ پڑھنا جائز ہے، اگر حجاج کا امیر ہو یا خلیفہ سفر پر ہو، یہ امام ابو حنیفہ رحمہ اللہ اور ابو یوسف کے نزدیک ہے، محمد کا خیال ہے کہ منی میں کوئی جمعہ نہیں ہے، کیونکہ وہ بستی ہے، حتی کہ وہ وہاں نماز عید پڑھنے کے قائل بھی نہیں ہیں، لیکن امام ابو حنیفہ اور ابو یوسف کے نزدیک یہ علاوہ حج کے موسم میں ’’مصر‘‘ بن جاتا ہے اور نماز عید نہ پڑھنے کا تعلق تخفیف سے ہے۔ البتہ اس پر سب کا اتفاق ہے کہ عرفات میں جمعہ نہیں ہوگا، کیونکہ اس میں کوئی عمارت نہیں ہے اور منی میں عمارتیں موجود ہیں۔(الہدایہ اولین: ص ۱۷۷، ۱۷۸) مولانا عبد الحی لکھنوی حنفی اسی مقام پر حاشیہ میں لکھتے ہیں: ’’مصر جامع‘‘ کی تعریف میں اختلاف ہے: (۱) امام ابو حنیفہ: وہ مقام، جہاں اہل شہر کی اشیائے ضرورت (اور سہولیات) موجود ہوں۔ (۲) ابو یوسف: ہر وہ جگہ جہاں امیر اور قاضی ہو جو شرعی احکام اور حدود کا نفاذ کرتا ہو، حسن نے بھی اپنی کتاب میں امام ابو حنیفہ کا یہ قول نقل کیا ہے۔ (۳) سفیان ثوری: ’’مصر جامع‘‘ وہ ہے جس کو لوگ دوسرے شہروں کا ذکر کرتے وقت شہر سمجھتے ہوں، جیسے بخارا اور سمرقند (۴) ابو عبد اللہ بلخی: میں نے جو سب سے بہترین رائے سنی ہے، وہ یہ ہے کہ جس مقام کے سب سے بڑی مسجد میں جمع ہوں لیکن وہ تنگ پڑ جائے، وہ ’’مصر جامع‘‘ ہوگا۔ (۵) امام ابو حنیفہ: وہ بڑا شہر جس میں گلیاں اور بازار ہوں اور اس میں پگڈنڈیاں ہوں اور لوگ اپنے حاجات میں اس کی طرف رجوع کرتے ہوں۔ شہر کی ’’خالی جگہ‘‘ سے مراد شہر سے متصل یا منفصل وہ گرگاہ و گذر ہیں جو شہری لوگوں کی مصلحتوں کے لیے خالی رکھے جاتے ہیں، محمد کے اندازے کے مطابق ایک تیر کی پھینک تک یا تین سو ہاتھ سے چار سو ہاتھ تک وسیع ہوتے ہیں، لیکن ان کی حد بندی کے بارے میں مزید تین اقوال یہ ہیں: ایک میل، دو میل، تین میل۔ (حاشیہ ختم ہوا، بعض عبارات کا مفہوم پیش کیا گیا) نبی کریم صلی اللہ علیہ وسلم کی جو روایت صاحب ہدایہ نے پیش کی، اس کے بارے میں اسی کتاب کے حاشیہ میں حافظ ابن حجر نے کہا: مجھے یہ حدیث نہیں ملی۔ خلاصہ کلام: ...... صاحب ہدایہ نے نماز عید اور نماز جمعہ کے لیے ’’مصر جامع‘‘ کی شرط لگانے کے لیے جس حدیث پر بنیاد رکھی اس کا وجود نہیں ملتا، پھر ’’مصر جامع‘‘ کی وضاحت کرتے کرتے پانچ چھ اقوال نقل کر دیے، جن میں سے تین اقوال امام ابو حنیفہ رحمہ اللہ کی طرف منسوب ہیں۔ پھر جب منی اور عرفات کی باری آئی تو وہاں عمارتوں کے ہونے یا نہ ہونے کا فرق کھڑا کر دیا، حالانکہ صرف عمارتوں کا نام شہر نہیں ہے۔ اسی طرح جب شہر کی خالی جگہ کی پیمائش کا مسئلہ کھڑا ہوا تو پھر چار پانچ اقوال بن گئے۔ بہر حال یہ تو حنفی فقہا ہی فیصلہ کریں گے کہ کس قول کو کس دلیل کی روشنی میں کیوں ترجیح دی جائے۔ لیکن اتنی حدود و قیود کے باوجود حنفی لوگ تقریباً ہر گاؤں میں نماز عید کا اور اکثر و بیشتر دیہاتوں میں نماز جمعہ کا اہتمام بھی کرتے ہیں اور امام ابو حنیفہ کی تقلید پر زور بھی دیتے ہیں اور ان اہل حدیث لوگوں پر سخت طعن بھی کرتے ہیں جو دیہاتوں میں نماز جمعہ کی ادائیگی کا فتوی دیتے ہیں یا اس کا اہتمام کرتے ہیں؟ سبحان اللہ! شعور والا اتنا کچھ سن کر کیا کرے گا؟! آج کل یہ فلسفہ بھی سنائی دیتا ہے کہ جس گاؤں میں جمعہ کی نماز شروع کر دی جائے، وہاں اس کو چھوڑا نہیں جا سکتا۔ ارے! جہاں نماز جمعہ ہوتی ہی نہیں، وہاں شروع کیسے ہوگی؟! ہم نے قرآن و حدیث کی روشنی میں جواب دے دیا ہے اور فقہ حنفی کی معتبر کتاب کا اقتباس بھی پیش کر دیا ہے، اللہ تعالی نے اپنے بندوں کو شرعی مسائل سمجھنے کا شعور عطا کر رکھا ہے۔ اگر حسن نیت کے ساتھ اور بے جا تعصب سے بچ کر مطالعہ کیا جائے تو حق واضح ہو جاتا ہے۔ واللہ اعلم بالصواب۔"}],[1062,"جناب محمد بن کعب رحمہ اللہ کہتے ہیں کہ میں نے بنو وائل کے ایک آدمی سے سنا وہ روایت کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’ہر مسلمان پر جمعہ واجب ہے سوائے عورت، بچہ اور غلام کے۔‘‘","",{"k":"ضعيف: أخرجه الامام الشافعى في المسند: 259، شرح كي ابتدا ميں مذكورہ حديث ديكهيں۔","e":"سیدنا طارق بن شہاب رضی اللہ عنہ سے اس حدیث کو نبی صلی اللہ علیہ وسلم سے بیان کرتے ہیں اس میں لفظ ’’مریض‘‘ کا اضافہ ہے۔ طارق بن شہاب رضی اللہ عنہ نے نبی کریم صلی اللہ علیہ وسلم کو دیکھا تو ہے مگر سنا کچھ نہیں۔","f":"یہ پوری حدیث یوں ہے: عَنْ طَارِقِ بْنِ شِهَابٍ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: «الْجُمُعَةُ حَقٌّ وَاجِبٌ عَلَى كُلِّ مُسْلِمٍ فِي جَمَاعَةٍ إِلَّا أَرْبَعَةً: عَبْدٍ مَمْلُوكٍ أَوْ امْرَأَةٍ أَوْ صَبِيٍّ أَوْ مَرِيضٍ» ...... سیدنا طارق بن شہاب رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم نے فرمایا: ’’ہر مسلمان پر واجب حق ہے کہ وہ جماعت کے ساتھ جمعہ ادا کرے، ما سوائے چار افراد کے: غلام، عورت، بچہ اور بیمار۔‘‘(صحیح، ابوداود: ۱۰۶۷) (م،م) ہمارے شیخ رحمہ اللہ نے کہا: اکثر اہل علم کے نزدیک جمعہ فرض عین ہے جبکہ کچھ علماء کے نزدیک جمعہ فرض کفایہ ہے اور یہ صرف ان لوگوں پر فرض ہے جن میں مذکورہ شروط پائی جائیں، عقل، شعور، بلوغت، آزادی، مذکر ہونا اور مقیم ہونا۔ اگر کوئی شرعی عذر مانع ہو تو الگ بات ہے۔ بچہ اور وہ شخص جس کا ذہنی توازن درست نہ ہو (مجنون) پر جمعہ فرض نہیں بلکہ وہ شرعی طور پر مکلف ہی نہیں (ان لوگوں پر بدنی احکامات لاگو نہیں ہوتے کیونکہ ان کے وجود میں کسی نقص پایا جاتا ہے، آئمہ اس بات پر متفق ہیں کہ خواتین پر بھی جمعہ کی ادائیگی فرض نہیں ہے۔ اکثر اہل علم کا موقف ہے کہ غلام بھی جمعہ کی فرضیت سے مستثنی ہے۔ امام داؤد ظاہری رحمہ اللہ نے کہا: غلام پر جمعہ فرض ہے۔ (عمومی دلائل کی وجہ سے) حسن بصری رحمہ اللہ اور قتادہ نے کہا: معاہد غلام پر جمعہ پڑھنا واجب ہے، امام اوزاعی رحمہ اللہ کا بھی یہی قول ہے۔ معاہد غلام وہ ہوتا ہے جس نے اپنے مالک سے معاہدہ کر لیا ہے کہ وہ آزاد کام کاج کرے گا اور مالک کو یومیہ کی بنیاد پر اتنی رقم ادا کرے گا، یا سال میں اتنی رقم ادا کرنے کا پابند ہوگا۔(ع،س) مسافر پر جمعہ واجب نہیں، ابراہیم نخعی رحمہ اللہ اور زہری رحمہ اللہ نے کہا: اگر مسافر نے اذان سن لی ہے تو جمعہ کے لیے آنا اس کے حق میں ضروری ہو گیا ہے۔ یاد رہے کہ وہ شخص جس پر جمعہ فرض تو نہیں البتہ وہ جمعہ پڑھ لیتا ہے تو جمعہ کی ادائیگی سے نماز ظہر ساقط ہو جائے گی اور ان کا جمعہ درست ہے۔ سیدنا عبداللہ بن مسعود رضی اللہ عنہ نے جمعہ والے دن عورتوں سے مخاطب ہو کر کہا: جب تم امام کے ساتھ نماز پڑھو تو اس کی اقتداء کرو، (یعنی دو رکعت ہی پڑھو) اور جب علیحدہ پڑھو تو چار رکعت ادا کرو۔ امام محمد رحمہ اللہ نے کہا: ہر وہ شخص جس پر جمعہ فرض تو نہیں اگر وہ نماز ظہر جمعہ ختم ہونے سے پہلے پڑھ لے تو جائز ہے اور جن پر جمعہ کی ادائیگی فرض ہے ان کے لیے یہ درست نہیں ہے کہ جمعہ ختم ہونے سے پہلے ظہر پڑھ لیں۔ ہر وہ شخص جس پر جمعہ فرض ہے زوال آفتاب کے بعد جمعہ پڑھے بغیر اس کے لیے سفر کا آغاز کرنا جائز نہیں ہے۔ اگر وہ فجر طلوع ہونے کے بعد اور زوال آفتاب سے قبل اپنا سفر شروع کرتا ہے تو پھر کوئی مضائقہ نہیں، البتہ ناپسندیدہ بات ہے کیونکہ جمعہ فوت ہو جانے کا قوی اندیشہ ہے۔ اگر سفر نیکی اور اطاعت پر مبنی ہو تو پھر الگ بات ہے۔ مثلاً حج یا جہاد کے لیے سفر درپیش ہے تو اس صورت میں سفر کے لیے نکلنا اولی اور بہتر ہے درج ذیل حدیث کی بنا پر۔"}],[1063,"سیدنا عبداللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم نے سیدنا عبداللہ بن رواحہ رضی اللہ عنہ کو ایک سریہ میں بھیجا، اتفاق سے وہ دن جمعہ کا تھا، ان کے ساتھی صبح صبح ہم پر روانہ ہو گئے مگر انھوں نے کہا: میں پیچھے رہ کر رسول اللہ صلی اللہ علیہ وسلم کی اقتداء میں جمعہ پڑھ کر روانہ ہوں گا اور اپنے ساتھیوں سے جا ملوں گا، چنانچہ انھوں نے نبی صلی اللہ علیہ وسلم کی اقتداء میں جمعہ پڑھا تو آپ نے دیکھ لیا اور پوچھا: ’’اپنے ساتھیوں کے ہمراہ آپ نے صبح صبح کوچ کیوں نہیں کیا۔‘‘ سیدنا عبداللہ بن رواحہ رضی اللہ عنہ نے کہا: میرا پروگرام تھا کہ آپ کے ساتھ نماز جمعہ پڑھ کر سفر کروں گا اور ساتھیوں تک پہنچ جاؤں گا، اس پر آپ صلی اللہ علیہ وسلم نے فرمایا: ’’تم روئے زمین پر موجود ہر چیز بھی اللہ کی راہ میں خرچ کرو، تو بھی ان کے صبح کے سفر کی فضیلت کو نہیں پہنچ سکتے۔‘‘","",{"k":"ضعيف الاسناد: أخرجه الترمذى: 527","e":"بعض علماء کا خیال ہے کہ جمعہ والے دن صبح کے وقت سفر کا آغاز نہ کیا جائے بلکہ جمعہ کے بعد سفر شروع کیا جائے۔ اہل الرائے کا کہنا ہے کہ زوال کے بعد سفر کرنا جائز ہے، جب جمعہ کا وقت ختم ہونے سے پہلے پہلے علاقے سے نکلنا ممکن ہو۔ مروی ہے کہ سیدنا عمر بن خطاب رضی اللہ عنہ نے ایک شخص جو سفر کرنے کی پوری تیاری کر چکا تھا، کو یہ کہتے ہوئے سنا: آج جمعہ کا دن نہ ہوتا تو میں ضرور سفر پر روانہ ہو جاتا، سیدنا عمر رضی اللہ عنہ نے کہا: آپ سفر کریں کہ جمعہ سفر سے مانع نہیں ہے۔(مسند شافعی: ۱۸۸)","f":"راجح بات یہی ہے کہ مسافر پر جمعہ فرض نہیں جبکہ وہ حالت سفر میں ہوا اور اس پر مسافر کا لفظ صادق آتا ہو، اس لیے کہ آپ نے دوران حج عرفات میں جمعہ نہیں پڑھا بلکہ ظہر ادا کی، البتہ اگر کوئی جمعہ پڑھ لے تو درست ہے۔ مسافر شخص امامت کرائے تو بھی جائز ہے۔(ع،س)"}],[1064,"سیدنا سلمان فارسی رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جو شخص جمعہ کے دن غسل کرے، اور اچھی طرح پاکیزگی اختیار کرے، تیل لگائے یا گھر کی خوشبو لگائے، پھر جمعہ کی نماز کے لیے نکلے اور دو انسانوں کے درمیان تفریق نہ کرے، (یعنی ان کے درمیان نہ بیٹھے) پھر جس قدر نوافل اس کے مقدر میں ہیں ادا کرے، پھر امام کے خطبہ کے دوران خاموش رہے تو اس کے گناہ جو اس جمعہ اور دوسرے جمعہ کے درمیان میں ہوں، معاف کر دیئے جاتے ہیں۔‘‘","",{"k":"أخرجه البخارى: 883"}],[1065,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے (جمعہ کے روز) غسل کیا اور جمعہ پڑھنے کے لیے آیا، پھر جس قدر نوافل اس کے مقدر میں ہیں ادا کیے، پھر خاموش رہا یہاں تک کہ امام خطبہ دینے سے فارغ ہوا تو اس کے ساتھ نماز (فرض دو رکعت) پڑھی، تو اس کے لیے اس جمعہ اور دوسرے جمعہ کے مابین (صادر ہونے والے گناہ) معاف کر دیئے جاتے ہیں اور مزید تین دنوں کے بھی۔‘‘","",{"k":"مسلم: 857"}],[1066,"سیدنا ابو سعید خدری رضی اللہ عنہ اور سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے جمعہ کے دن غسل کیا اور مسواک کی اور خوشبو بھی لگائی اور بہترین کپڑے زیب تن کیے، پھر جمعہ کے لیے نکلا حتی کہ مسجد آیا اور لوگوں کی گردنیں نہ پھلانگیں، پھر نفل نماز پڑھی جو اس کے لیے مقدر کی گئی، پھر خاموش رہا جب امام خطبے کے لیے نکلا تو یہ اس کے لیے اس جمعہ اور سابقہ جمعہ کے مابین صادر ہونے والے گناہوں کا کفارہ ہے۔‘‘","",{"k":"هذا حديث حسن: أخرجه ابوداود: 343","e":"سیدنا ابو ہریرہ رضی اللہ عنہ نے بیان کیا: ’’اور مزید تین دن کے گناہ بھی معاف ہو جاتے ہیں۔‘‘ کیونکہ اللہ تعالیٰ فرماتا ہے:\n﴿ مَنْ جَاءَ بِالْحَسَنَةِ فَلَهُ عَشْرُ أَمْثَالِهَا ﴾ [سورۂ انعام: ۱۶۰]\n’’جو شخص نیک کام کرے گا اس کو اس کے دس گنا ملیں گے۔‘‘\n(حسن، ابوداود: ۳۴۳) «يستن» ’’مسواک کرنا‘‘، یعنی دانتوں کو مسواک کے ساتھ مانجنا اور رگڑنا۔"}],[1067,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جب جمعہ کا دن آتا ہے تو مسجد کے ہر دروازے پر فرشتے آنے والوں کے نام درجہ وار لکھتے ہیں لیکن جب امام خطبہ دینے کے لیے آتا ہے تو دفاتر بند کر دیئے جاتے ہیں اور فرشتے خطبہ سننے میں مشغول ہو جاتے ہیں، نماز کے لیے سب سے پہلے آنے والا اونٹ کی قربانی دینے والے کی طرح لکھا جاتا ہے، اس کے بعد آنے والا گائے کی قربانی دینے والے کی طرح، پھر مینڈھے کی قربانی دینے والے کی طرح حتی کہ مرغی اور انڈے کا تذکرہ کیا۔‘‘","",{"k":"أخرجه البخارى: 929، و مسلم: 850","e":"جناب خلیل بن احمد نحوی نے کہا: ’’تہجیر‘‘ اور ’’تبکیر‘‘ کا معنی ایک ہے اور مراد یہ ہے کہ جمعہ کی ادائیگی کے لیے بروقت پہنچنا۔"}],[1068,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’سورج جمعہ کے دن کے علاوہ کسی افضل دن میں طلوع نہیں ہوتا اور ہر جانور جمعہ والے دن گھبراتا ہے سوائے ثقلین یعنی جن وانسان کے، مسجد کے ہر دروازے پر دو فرشتے موجود رہتے ہیں جو سب سے پہلے آنے والوں کا اندراج کرتے ہیں، کوئی اونٹ کی قربانی دینے والے کی طرح لکھا جاتا ہے، کوئی گائے کی قربانی دینے والے کی طرح لکھا جاتا ہے، کوئی بکری کی قربانی دینے والے کی طرح لکھا جاتا ہے، کوئی پرندہ بطور تقرب پیش کرنے والے کی طرح لکھا جاتا ہے، اور کوئی انڈہ بطور تقرب پیش کرنے والے کی طرح لکھا جاتا ہے اور جب امام خطبہ کے لیے آتا ہے تو دفاتر بند کر دیئے جاتے ہیں۔‘‘","",{"k":"هذا حديث صحيح: أخرجه الامام احمد في المسند: 7687"}],[1069,"سیدنا ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے جمعہ کے دن غسل جنابت کیا، پھر جمعہ کے لیے آیا تو اس نے گویا ایک اونٹ قربان کیا اور جو دوسری ساعت میں آیا تو اس نے گویا گائے قربان کی اور جو تیسری گھڑی میں آیا اس نے گویا مینڈھا قربان کیا، جو چوتھی ساعت میں آیا اس نے گویا مرغی تقرب کے لیے پیش کی اور جو پانچویں ساعت میں آیا اس نے گویا انڈا تقرب کے لیے پیش کیا، پھر جب امام نکل آتا ہے تو فرشتے بھی ذکر سننے کے لیے حاضر ہو جاتے ہیں۔‘‘","",{"k":"أخرجه البخارى: 881، و مسلم: 850","f":"باب کے اندر مذکورہ احادیث میں یہ سلسلہ ذکر ثواب مختلف جانوروں کے ساتھ مرغی، پرندے اور انڈے کا بھی ذکر ہے۔ اس کے متعلق شیخ الحدیث عبید اللہ مبارکپوری رحمہ اللہ فرماتے ہیں: (والمشكل ذكر الدجاجة والبيضة لان الهدى لا يكون منهما واجب، بانه من باب المشاكلة اى من سمية الشيء باسم قرينة والمراد بالاهداد هنا التصديق لما دل عليه لفظ قرب فى رواية اخرى وهو يجوز بهما) ’’مرغی اور انڈے کا بھی ذکر آیا ہے حالانکہ ان کی قربانی نہیں ہوتی، اس کا جواب یہ دیا گیا ہے کہ یہاں یہ ذکر باب مشاکلہ کے طور پر ہے یعنی کسی چیز کا ایسا نام رکھ دینا جو اس کے قرین کے نام ہو یہاں قربانی سے مراد صدقہ کرنا ہے جس پر بعض روایات میں آمدہ لفظ ’’قرب‘‘ دلالت کرتا ہے اور قربت حاصل کرنے کے لیے ان ہر دو چیزوں کو بھی بطور خیرات دیا جا سکتا ہے۔‘‘ بہر حال اس حدیث سے مرغی اور انڈے کی قربانی کا جواز نکالنا کسی طرح صحیح نہیں ہے۔ تاخیر سے آنے والے کا جمعہ تو یقیناً ہو جاتا ہے مگر وہ مذکورہ فضیلت سے بالکل محروم رہتا ہے۔(ع،س) امام محمد رحمہ اللہ نے کہا: احادیث میں مذکور شدہ فضیلت کی ساعتوں کے متعلق علماء کے مابین اختلاف پایا جاتا ہے۔ بعض کا کہنا ہے کہ زوال آفتاب کے بعد یہ لطیف گھڑیاں ہوتی ہیں جن کا ان ساعتوں کے ساتھ کچھ تعلق نہیں جن پر روز و شب کی آمد و شد کا انحصار ہے۔ یاد رہے ’’رواح‘‘ کا لفظ زوال کے بعد روانگی پر بولا جاتا ہے، اگر کوئی آدمی دن کے پہلے پہر سفر کے لیے نکلتا ہے تو عرب غدا الرجل فی حاجتہ کا جملہ بولتے ہیں اور آدھا دن گزر جانے کے بعد سفر شروع کیا جائے تو راح کا لفظ بولتے ہیں۔ زوال کے بعد جمعہ کے وقت کے لیے صرف پانچ ساعتیں بچتی ہیں۔ یہاں ساعت سے مراد کچھ وقت ہے جیسے کوئی کہے: میں فلاں کے پاس ساعت بھر ٹھہرا۔ ’’متعین اور مصرف (ساعة) ’’گھنٹہ‘‘ مراد نہیں ہے یہ مطلب امام مالک رحمہ اللہ سے منقول ہے۔ ایک قول یہ ہے کہ اس سے مراد دن کے مختلف پہر ہیں۔ تو اس میں اس شخص کے لیے فضیلت کا اظہار ہے جو زوال سے کہیں پہلے جمعہ پڑھنے کے لیے مسجد میں آجاتا ہے اس شخص کی نسبت سے جو اس کے بعد آتا ہے۔ اس صورت میں لفظ راح کا استعمال بطور مثال اور انجام کے ہے جیسے حج کے ارادے سے نکلنے والے کو حاجی کہہ دیا جاتا ہے حالانکہ اس نے حج نہیں کیا ہوتا اور غزوے کے لیے نکلنے والے کو غازی اور مجاہد کے لقب سے بلایا جاتا ہے حالانکہ غزوہ کرنا تو ابھی باقی ہے۔ «من راح الی الجمعة» جمعہ کی طرف دوڑ کر جانا، ذوق وشوق اور رغبت کے ساتھ وقت سے پہلے پہنچ جانا، پورے اہتمام کے ساتھ جانا وغیرہ معانی مراد ہیں، پچھلے پہر چلنا مراد نہیں ہے۔ عرب تروّح القوم کا جملہ بولتے ہیں اس میں وقت کا پہلو مد نظر نہیں ہوتا۔"}],[1070,"سیدنا اوس بن اوس ثقفی رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے جمعہ کے روز غسل کیا اور خوب اچھی طرح کیا اور جلدی آیا اور خطبے میں اول وقت پہنچا، امام سے قریب ہو کر بیٹھا اور کوئی لغو کام نہ کیا تو اس کے لیے ہر قدم پر ایک سال کے روزوں اور قیام کے عمل کا ثواب ہے۔‘‘","",{"k":"انظر الحديث الآتى"}],[1071,"سیدنا اوس بن اوس ثقفی رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے فرمایا: ’’جس نے جمعہ کے روز (اپنے سر کو) دھویا اور غسل کیا اور جلدی آیا اور خطبے میں اول وقت پہنچا، پیدل چل کر آیا اور سوار نہ ہوا، امام سے قریب ہو کر بیٹھا اور غور سے سنا اور لغو سے بچا، تو اس کے لیے ہر قدم پر ایک سال کے روزوں اور قیام کے عمل کا ثواب ہے۔‘‘","",{"k":"هذا حديث صحيح: أخرجه ابوداود: 345، وابن ماجه: 1087، والترمذى: 496، والنسائى: 3/97","e":"حدیث ہذا کی سند میں مذکور راوی ابو الاشعث صنعانی کا نام شراحیل بن آدہ شامی ہے۔ «مَنْ غَسَّلَ وَاغْتَسَلَ، ثُمَّ بَكَّرَ وَابْتَكَرَ» ان الفاظ کے کئی معانی ذکر کیے گئے ہیں۔ ایک قول یہ ہے کہ (غسّل واغتسل۔) (حرف ’س‘ کی تشدید اور باب افتعال کے ساتھ) دونوں لفظوں کا معنی ایک ہی ہے صرف تاکید اور مبالغہ مراد ہے، جیسے حدیث میں: «مشى ولم يركب» کے الفاظ آئے ہیں جبکہ معنی ایک ہی ہے۔ عرب گفتگو میں زور اور مبالغہ پیدا کرنے کے لیے اسی مادہ سے دوسرا لفظ بنا لیتے ہیں مثلاً: جادّ مجدّ، لیل لائل، شعر شاعر وغیرہ۔ ایک قول یہ ہے کہ غسّل حرف سین کی تشدید کے ساتھ، معنی ہے ’’سر کو اچھی طرح دھونا‘‘ اور ’’دھونے‘‘ کی خصوصیت یہ ہے کہ عرب لوگ لمبے بال رکھتے تھے اور انھیں دھونے میں محنت ہوتی تھی اور وقت لگتا تھا۔ لہذا اس کا تذکرہ بطور خاص کر دیا گیا اور (اغتسل) ’’کا معنی سارے جسم کو دھونا ہے‘‘۔ جناب مکحول اور ابن مبارک کا یہ قول ہے۔ ایک قول یہ ہے کہ غسّل وضو کے اعضاء کو دھونا اور اغتسل باقی جسم کو صاف کرنا ہے۔","f":"ابوداود کی ایک روایت میں ’’مَنْ غَسَّلَ رَأْسَهُ‘‘ (جس نے اپنے سر کو دھویا) کے الفاظ ہیں، لہذا اس حدیث کی مزید کوئی تاویل کرنے کی گنجائش نہیں ہے، جیسا کہ درج ذیل پیرا گراف میں بیان کیا گیا ہے، اسی روایت کے مطابق ترجمہ کیا گیا ہے۔(م،م) ایک قول کے مطابق غسّل کا مطلب ہے جس نے اپنی زوجہ کے ساتھ مباشرت کی اور اس پر بھی غسل لازم کر دیا۔ اس میں حکمت یہ ہے کہ اس طرح انسان نفسیاتی اور جذباتی طور پر بہت پرسکون ہو جاتا ہے اور ذہن پراگندہ نہیں ہوتا اور عبادت میں یکسو رہتا ہے یہ نظر محفوظ ہو جاتی ہے اور اغتسل کا مطلب ہے کہ بذات خود غسل کیا، یہ معنی امام وکیع رحمہ اللہ سے منقول ہے۔ «بكّر وابتكر» ایک قول کے مطابق بکر کا مطلب ہے ’’نماز کو اول وقت ادا کیا‘‘ اور (ابتکر) کا مطلب ’’خطبہ کے آغاز میں پہنچا از اول تا آخر خطبہ سماعت کیا۔‘‘ ابن انباری رحمہ اللہ نے بکّر کا معنی کیا ہے ’’حمد کے لیے نکلنے سے پہلے صدقہ کرنا۔‘‘ انھوں نے یہ مفہوم ایک حدیث سے لیا ہے: «باكروا بالصدقة فان البلاء لا يتخطاها» ’’صدقہ کرنے میں جلدی کرو اس لیے کہ مصیبتیں صدقے کو عبور نہیں کر سکتیں۔‘‘ (ضعیف، معجم اوسط طبرانی) «ولم يلغ» ’’اور لغو سے بچا‘‘ اس سے مراد لغو گفتگو نہ کرنا ہے کیونکہ اثناء خطبہ ہر قسم کی بات خطبہ سے لوگوں کی توجہ ہٹا دے گی، یہ معنی ایک حدیث نبویہ سے اخذ کیا گیا ہے کہ آپ نے فرمایا: ’’جب تم خطبہ کے دوران میں اپنے ساتھی سے کہو گے: خاموش رہو، تو تم نے لغو کیا۔‘‘(صحیح بخاری: ۹۳۴، صحیح مسلم: ۸۵۱) یہ بھی مروی ہے کہ ’’جو خطبہ کے دوران کنکریوں سے کھیلتا ہے اس نے لغو کیا۔‘‘(صحیح مسلم: ۸۵۷) دوسرا مفہوم یہ ہے کہ ’’وہ ثواب سے محروم ہو گیا۔‘‘ تیسرا یہ کہ ’’وہ ناکام اور نامراد ہو گیا۔‘‘ اللہ تعالیٰ کا فرمان ہے:\n﴿ لَا يَسْمَعُونَ فِيهَا لَغْوًا ﴾ [سورہ واقعہ: ۲۵]\n’’نہ وہاں بکواس سنیں گے۔‘‘\nیعنی ایسی کلام جو حد درجہ سطحی اور شرفاء کے قابل نہ ہو۔ ہر چیز جو پھینک دیئے جانے کے قابل ہوا سے ’’لغو‘‘ کہتے ہیں۔ یہ لفظ تین ابواب سے آتا ہے، قرآن مجید میں ہے:\n﴿ وَالْغَوْا فِيهِ ﴾ [سورہ فصلت: ۲۶]\n’’اور شور ڈالو۔‘‘\n۔ کفار ایک دوسرے سے کہتے: جب قرآن پڑھا جائے تو تم شور مچاؤ تاکہ لوگ قرآن سن نہ سکیں۔"}],[1072,"سیدنا انس بن مالک رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم سورج ڈھلنے پر جمعہ پڑھا کرتے تھے۔","",{"k":"أخرجه البخارى: 904","e":"یہ حدیث دلیل ہے کہ نبی صلی اللہ علیہ وسلم کا جمعہ زوال کے فوراً بعد ہوتا تھا اور مختصر ہونے کی بنا پر جلدی ختم ہو جاتا تھا۔ زوال سے پہلے جمعہ ادا کرنا جائز نہیں ہے جیسا کہ بعض لوگوں کا خیال ہے۔"}],[1073,"ایاس بن سلمہ بن اکوع اپنے والد (سلمہ بن اکوع رضی اللہ عنہ) سے بیان کرتے ہیں کہ ہم رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعہ پڑھا کرتے تھے، اس کے بعد جب واپس لوٹتے تو دیواروں کا سایہ نہیں ہوتا تھا۔","",{"k":"أخرجه البخارى: 1687، و مسلم: 860","f":"چونکہ آپ صلی اللہ علیہ وسلم کا خطبہ مختصر اور جامع ہوا کرتا تھا اور نماز قدرے لمبی ہوتی تھی اس لیے صحابہ کرام رضی اللہ عنہم واپسی پر دیواروں کا اتنا سایہ نہ پاتے تھے کہ اس سے سایہ حاصل کر سکتے، اس سے بعض لوگوں نے استدلال کیا ہے جمعہ قبل زوال ہوتا تھا مگر یہ استدلال بے محل ہے۔(ع،س)"}],[1074,"سیدنا سہل بن سعد رضی اللہ عنہ کا بیان ہے کہ ہم لوگ جمعہ کے بعد کھانا کھاتے اور قیلولہ کرتے تھے۔","",{"k":"أخرجه البخارى: 939، و مسلم: 859","e":"«غداء» دوپہر کے کھانے اور «قيلولة» نصف النہار میں استراحت کرنے کو کہتے ہیں۔ فن لغت کے امام ازہری رحمہ اللہ نے کہا: عرب لوگ دوپہر کے سونے کو قیلولہ اور مقیل کہتے ہیں خواہ نیند کے بغیر ہی کچھ دیر کے لیے لیٹا جائے۔ اس کی دلیل اللہ تعالیٰ کا فرمان ہے:\n﴿ وَأَحْسَنُ مَقِيلًا ﴾ [سورہ فرقان: ۲۴]\n’’اور خواب گاہ بھی عمدہ ہوگی۔‘‘\n۔ جبکہ جنت میں نیند نہ ہوگی (یعنی نیند، موت، بھوک، غم، اور اس قسم کے دیگر عوارض دنیا کا لازمہ ہیں جنت میں نہ ہوں گے)۔","f":"امام بغوی رحمہ اللہ اور امام ازہری رحمہ اللہ کی وضاحت سے یہ استدلال کر رہے ہیں کہ حضرات صحابہ کرام رضی اللہ عنہم جمعہ کے بعد کچھ دیر کے لیے یونہی لیٹ جاتے تھے تاکہ تازہ دم ہو جائیں۔ کوئی لمبا پورا قیلولہ نہ کرتے تھے اور جمعہ بعد از زوال ہی ادا کرتے تھے نہ کہ قبل الزوال۔ ویسے بھی جمعہ ظہر کا بدل ہے لہذا جو وقت نماز ظہر کا ہے وہی وقت جمعہ کا ہے، ہاں اتنا ضرور ہے کہ آپ صلی اللہ علیہ وسلم کا خطبہ مختصر اور بروقت ختم ہو جاتا تھا آجکل کے رواج کے مطابق بہت تاخیر سے نہ ہوتا۔ دوسرے یہ بات ذہن نشین رہے کہ دوپہر کا کھانا دیر کے کھایا جائے تو بھی اسے (غداء) ہی کہتے ہیں اور نصف النہار کی استراحت میں تاخیر کی جائے تو بھی اسے قیلولہ ہی کہتے ہیں لہذا جمعہ کے بعد کھانے اور قیلولہ کرنے سے یہ لازم نہیں آتا کہ جمعہ قبل الزوال ہوتا تھا۔(ع،س)"}],[1075,"سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم جب منبر پر تشریف فرما ہوتے تو (حاضرین کو) سلام کہتے۔","",{"k":"حديث حسن: أخرجه ابن ماجه: 1109"}],[1076,"جناب عامر بن عبداللہ اپنے والد (عبداللہ بن زبیر رضی اللہ عنہ) سے بیان کرتے ہیں، وہ کہتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم خطبہ دیتے وقت چھڑی کا سہارا لیتے تھے۔","",{"k":"رواه الهيثمى في الزوائد: 2/187، وعزاه للطبرانى في الكبير والبزار، وقال: فيه ابن لهيعة وفيه كلام"}],[1077,"سیدنا سائب بن یزید رضی اللہ عنہ سے روایت ہے، انھوں نے کہا: جمعہ کے روز جمعہ کی پہلی اذان امام کے منبر پر بیٹھنے کے وقت کہی جاتی تھی، عہد نبوت اور خلافت ابی بکر و عمر رضی اللہ عنہما میں یہی معمول رہا۔ جب سیدنا عثمان رضی اللہ عنہ کی خلافت آئی اور لوگ بھی بہت ہو گئے تو سیدنا عثمان رضی اللہ عنہ نے جمعہ کے روز تیسری اذان کا حکم دیا جو کہ زوراء مقام پر دی جاتی تھی۔","",{"k":"أخرجه البخارى: 912","e":"ایک سند میں یہ الفاظ آئے ہیں: «لَمْ يَكُنْ لِلنَّبِيِّ مُؤَذِّنٌ غَيْرُ وَاحِدٍ» ’’رسول اللہ صلی اللہ علیہ وسلم کا ایک ہی مؤذن تھا۔‘‘","f":"سیدنا عثمان رضی اللہ عنہ نے جمعہ کی پہلی اذان مسجد سے باہر بازار میں کہلوائی تاکہ زیادہ لوگ متوجہ ہو سکیں۔ آج کے دور میں لاؤڈ سپیکر کی وجہ سے مسجد کے اندر کہی ہوئی اذان سے بھی یہی مقصد حاصل ہوتا ہے، اس لیے اس اذان کا مسجد سے باہر دینا ضروری نہیں، جمعہ کی پہلی اذان خلفائے راشدین کی سنت ہے۔ اللہ کے رسول صلی اللہ علیہ وسلم نے فرمایا: ’’میری سنت اور ہدایت یافتہ خلفائے راشدین کی سنت اختیار کرو۔‘‘(سنن ابن ماجہ: ۴۲)۔ سنت نبوی کے مطابق صرف ایک اذان کہنا یا خلیفہ راشد کی سنت کے مطابق دو اذانیں کہنا، دونوں دونوں طرح جائز ہے، تاہم سنت نبوی کے مطابق ایک ہی اذان کہنا زیادہ بہتر ہے۔ البتہ بعض اہل علم کے نزدیک لاؤڈ سپیکر اور گھڑیوں کے عام ہونے کی وجہ سے موجودہ دور میں پہلی اذان کا جواز باقی نہیں رہتا، تاہم جہاں یہ چیزیں نہ ہوں تو وہاں ضرورت کے مطابق اس پر عمل کرنا جائز ہوگا بہر حال اسے ہم بدعت نہیں کہہ سکتے۔ واللہ اعلم (ع،س)"}],[1078,"سیدنا عبداللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم بروز جمعہ (کھڑے ہو کر) خطبہ دیتے تھے، پھر بیٹھ جاتے اور پھر کھڑے ہوتے جیسے تم لوگ آج کل کرتے ہو۔","",{"k":"أخرجه البخارى: 920، و مسلم: 861"}],[1079,"سیدنا جابر بن عبداللہ رضی اللہ عنہ بیان کرتے ہیں کہ نبی صلی اللہ علیہ وسلم جمعہ کے روز دو خطبے کھڑے ہو کر ارشاد فرماتے اور دونوں کے مابین بیٹھ کر فاصلہ کرتے۔","",{"k":"أخرجه مسلم: 862","e":"سیدنا ابن عمر رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم جب منبر پر تشریف لاتے تو بیٹھ جاتے حتی کہ مؤذن اذان سے فارغ ہو جاتا۔ پھر آپ کھڑے ہوتے اور خطبہ دیتے، پھر بیٹھ جاتے اور کلام نہ کرتے، پھر کھڑے ہوتے اور دوسرا خطبہ دیتے۔(صحیح، ابوداود: ۱۰۹۲)"}],[1080,"سیدنا عبداللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم اپنے صحابہ کو دوران سفر میں کھڑے ہو کر ایک کمان کا سہارا لے کر خطبہ دیتے تھے۔","",{"k":"رواه الهيثمى في الزوائد: 2/187، وعزاه للطبرانى في الكبير وقال: فيه ابو شيبة وهو ضعيف","e":"وروی أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا خَطَبَ يَعْتَمِدُ عَلَى عَنَزَتِهِ اعتمادًا\nمروی ہے کہ نبی صلی اللہ علیہ وسلم جب خطبہ ارشاد فرماتے تو ایک برچھی کا سہارا لیتے۔(مسند شافعی: ۳۴۲) امام بغوی رحمہ اللہ نے کہا: جمعہ کا خطبہ دینا ایک بھاری ذمہ داری اور دینی فریضہ ہے۔ دونوں خطبے کھڑے ہو کر دینا اور ان کے مابین بیٹھ کر فاصلہ کرنا فرض ہے۔ بغیر شرعی عذر کے بیٹھ کر خطبہ دینا جائز نہیں ہے جبکہ بعض نے بیٹھ کر خطبہ دینا جائز قرار دیا ہے۔","f":"حدیث دلائل، قرون اولی کے عمل اور قرآن مجید کی نص\n﴿ وَتَرَكُوكَ قَائِمًا ﴾ [سورہ جمعہ: ۱۱]\n’’لوگ آپ کو کھڑے (خطبہ دیتے ہوئے) چھوڑ جاتے ہیں۔‘‘\nسے معلوم ہوتا ہے کہ جمعہ کے دونوں خطبے کھڑے ہو کر دینا مسنون ہے اور جو شخص بغیر کسی شرعی عذر کے ان میں سے کوئی بھی خطبہ بیٹھ کر دینا مسنون سمجھے تو ایسا شخص بدعتی ہوگا۔ ذہن نشین رہے کہ خطبہ عید کی اعتبار سے دو ہیں تین نہیں، مسنون خطبوں سے پہلے ’’تقریر یا بیان‘‘ وغیرہ اس عدد کو بڑھا دیتا ہے اس لیے جائز نہیں، یہ سنت رسول سے انحراف ہے۔ جو لوگ مسنون خطبوں سے پہلے منبر پر بیٹھ کر بیان یا تقریر کرتے ہیں انھیں اپنے اس خلاف سنت عمل پر غور کرنا چاہیے۔(ع،س) درج ذیل حدیث سے لاٹھی کا ثبوت ملتا ہے: عَنْ شُعَيْبِ بْنِ زُرَيْقٍ الطَّائِفِيِّ قَالَ جَلَسْتُ إِلَى رَجُلٍ لَهُ صُحْبَةٌ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُقَالُ لَهُ الْحَكَمُ بْنُ حَزْنٍ الْكُلَفِيُّ فَأَنْشَأَ يُحَدِّثُنَا قَالَ وَفَدْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَابِعَ سَبْعَةٍ أَوْ تَاسِعَ تِسْعَةٍ فَدَخَلْنَا عَلَيْهِ فَقُلْنَا: يَا رَسُولَ اللَّهِ! زُرْنَاكَ فَادْعُ اللَّهَ لَنَا بِخَيْرٍ، فَأَمَرَ بِنَا أَوْ أَمَرَ لَنَا بِشَيْءٍ مِنَ التَّمْرِ وَالشَّأْنِ إِذْ ذَاكَ دُونَ فَأَقَمْنَا بِهَا أَيَّامًا شَهِدْنَا فِيهَا الْجُمُعَةَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَامَ مُتَوَكِّئًا عَلَى عَصًا أَوْ قَوْسٍ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ كَلِمَاتٍ خَفِيفَاتٍ طَيِّبَاتٍ مُبَارَكَاتٍ ثُمَّ قَالَ: «أَيُّهَا النَّاسُ إِنَّكُمْ لَنْ تُطِيقُوا أَوْ لَنْ تَفْعَلُوا كُلَّ مَا أُمِرْتُمْ بِهِ وَلَكِنْ سَدِّدُوا وَأَبْشِرُوا»...... شعیب بن زریق طائفی رضی اللہ عنہ سے روایت ہے، وہ کہتے ہیں: میں حکم بن حزن نامی ایک شخص کے پاس بیٹھا تھا جو رسول صلی اللہ علیہ وسلم کی صحبت میں رہ چکا تھا، وہ ہم سے حدیث بیان کرنے لگا اور اس نے کہا: ایک مرتبہ میں سات یا نو آدمیوں کے وفد کے ہمراہ حضور صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوا، پس جب ہم آپ صلی اللہ علیہ وسلم کی خدمت میں حاضر ہوئے تو ہم نے کہا: اے اللہ کے رسول! ہم آپ کی زیارت کی غرض سے آئے ہیں، پس ہمارے لیے دعائے خیر فرمائیے، آپ صلی اللہ علیہ وسلم نے ہمارے لیے کچھ کھجوریں لانے کا حکم فرمایا، ان دنوں مسلمانوں کی مالی حالت بہت خراب تھی، پھر ہم چند روز مدینہ میں رہے، ان دنوں میں ہم نے رسول اللہ صلی اللہ علیہ وسلم کے ساتھ جمعہ بھی پڑھا، پس آپ صلی اللہ علیہ وسلم ایک لاٹھی یا کمان پر سہارا لگا کر کھڑے ہوئے اور چند کلمات سے اللہ تعالیٰ کی حمد و ثنا کی، وہ کلمات ہلکے پھلکے نہایت پاکیزہ اور مبارک تھے، پھر آپ نے فرمایا: ’’اے لوگو! تم تمام احکامات نہ بجا لا سکو گے، لیکن راہ صواب پر چلتے رہو اور خوشخبری سناؤ۔‘‘(صحیح، ابوداود: ۱۰۹۶)۔(م،م)"}],[1081,"جناب جعفر بن عمرو بن حریث اپنے والد (سیدنا عمرو بن حریث رضی اللہ عنہ) سے بیان کرتے ہیں، انھوں نے کہا: رسول اللہ صلی اللہ علیہ وسلم نے لوگوں سے خطاب کیا اور آپ نے سیاہ عمامہ، پگڑی زیب سر کیا ہوا تھا۔","",{"k":"أخرجه مسلم: 1359"}],[1082,"سیدنا عبداللہ بن عباس رضی اللہ عنہ بیان کرتے ہیں کہ نبی کریم صلی اللہ علیہ وسلم نے لوگوں کو خطبہ دیا، آپ نے سیاہ پگڑی پہنی ہوئی تھی۔","",{"k":"صحيح: أخرجه الترمذى في الشمائل: 111","e":"«دسماء» سے مراد کالے رنگ کا عمامہ ہے، چربی سے لتھڑا ہوا عمامہ مراد نہیں ہے اگر چہ لغت میں دسم کے معنیٰ چکناہٹ اور چربی کے ہیں مگر حدیث میں اس لفظ کے یہ معنیٰ ہرگز نہیں اور نہ آپ کی طہارت و نظافت کے ساتھ اس معنیٰ کو کوئی مناسبت ہے۔ امام بغوی رحمہ اللہ نے کہا: یہ کیسے ممکن ہے کہ آپ لوگوں کو تو جمعہ کے لیے نہا دھو کر، اچھا لباس زیب تن کر کے اور خوشبو لگا کر آنے کا حکم صادر فرمائیں اور خود اس سے گریز کریں جبکہ امام ان استحبابی احکامات پر عمل پیرا ہونے کا زیادہ حقدار ہے اور آپ صلی اللہ علیہ وسلم کی طبیعت میں جو نظافت اور پاکیزگی پائی جاتی تھی وہ چکناہٹ والا معنیٰ کرنے سے مانع ہے۔ جمعہ، عید اور خاص مواقع پر عمدہ لباس کا اہتمام مسنون و مستحب ہے۔ نبی صلی اللہ علیہ وسلم سے مروی ہے کہ آپ نے فرمایا: «مَا عَلَى أَحَدِكُمْ إِنْ وَجَدَ أَوْ مَا عَلَى أَحَدِكُمْ إِنْ وَجَدْتُمْ أَنْ يَتَّخِذَ ثَوْبَيْنِ لِيَوْمِ الْجُمُعَةِ، سِوَى ثَوْبَيْ مِهْنَتِهِ» ...... ’’کیا حرج ہے اگر تم میں سے کوئی آدمی کام کاج کے کپڑوں کے علاوہ جمعے کے دن نماز جمعہ کی حاضری کے لیے دو کپڑے خرید لے۔‘‘(صحیح، ابوداود: ۱۰۷۸، وابن ماجہ: ۱۰۹۵)"}],[1083,"سیدنا جابر بن سمرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نبی کریم صلی اللہ علیہ وسلم کے ساتھ جمعہ کی نماز پڑھا کرتا تھا، آپ کی نماز اور خطبہ دونوں معتدل (نہ زیادہ طویل اور نہ زیادہ چھوٹے) ہوتے تھے۔","",{"k":"أخرجه مسلم: 866","e":"سیدنا جابر رضی اللہ عنہ ہی بیان کرتے ہیں کہ آپ کے دو خطبے ہوا کرتے تھے اور آپ ان دونوں کے درمیان بیٹھا کرتے تھے آپ (خطبات میں) قرآن کی تلاوت فرماتے اور لوگوں کو وعظ و نصیحت فرمایا کرتے تھے۔(صحیح مسلم: ۸۶۲) سیدنا عمار رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ صلی اللہ علیہ وسلم کو یہ فرماتے ہوئے سنا: «إِنَّ طُولَ صَلَاةِ الرَّجُلِ، وَقِصَرَ خُطْبَتِهِ، مَئِنَّةٌ مِنْ فِقْهِهِ، فَأَطِيلُوا الصَّلَاةَ، وَاقْصُرُوا الْخُطْبَةَ» ...... ’’بلا شبہ لمبی نماز پڑھانا اور مختصر خطبہ دینا آدمی کی دانش مندی کی دلیل ہے لہذا نماز لمبی پڑھایا کرو اور خطبہ مختصر دیا کرو۔‘‘(صحیح مسلم: ۸۶۹) «مئنة» ’’علامت‘‘ یہ (مفعلة) کا وزن ہے یعنی مختصر خطبہ اس بات کا پتہ دیتا ہے کہ خطیب سمجھدار اور گفتگو کا سلیقہ رکھتا ہے۔ امام احمد رحمہ اللہ نے کہا: سنت طریقہ یہی ہے کہ خطبہ جمعہ کو بہت زیادہ طویل نہ کیا جائے۔ امام شافعی رحمہ اللہ نے کہا: خطبہ مختصر، جامع اور بچے تلے الفاظ پر مشتمل ہونا چاہیے۔ بے جا طوالت سے پرہیز کیا جائے۔ خطبہ کے کم از کم عناصر تین ہیں: ایک اللہ تعالیٰ کی حمد و ثنا کرنا، دوسرا اللہ کے نبی صلی اللہ علیہ وسلم پر درود و سلام بھیجنا، تیسرا حاضرین کو اللہ تعالیٰ سے ڈرتے رہنے کی تلقین کرنا، دو خطبوں میں یہ چیزیں ضروری ہونی چاہیں مزید یہ کہ پہلے خطبے میں قرآن مجید کی آیت پڑھ کر وعظ کیا جائے اور دوسرے میں مومنوں کے لیے دعائیں کی جائیں، یہ کل پانچ باتیں ہوئیں۔ امام شافعی رحمہ اللہ کے نزدیک یہ پانچوں باتیں خطبہ کے عناصر ہیں اور ان میں اگر ایک بھی کم ہے تو خطبہ درست نہیں ہے۔"}],[1084,"جناب صفوان بن یعلیٰ اپنے والد (سیدنا یعلیٰ بن امیہ رضی اللہ عنہ) سے بیان کرتے ہیں، انھوں نے کہا: میں نے منبر پر نبی کریم صلی اللہ علیہ وسلم کو یہ آیت پڑھتے ہوئے سنا:\n﴿ وَنَادَوْا يَا مَالِكُ لِيَقْضِ عَلَيْنَا رَبُّكَ ﴾ [سورہ زخرف: ۷۷]\n’’اور پکار پکار کر کہیں گے کہ اے مالک! تیرا رب ہمارا کام ہی تمام کر دے۔‘‘","",{"k":"أخرجه البخارى: 4819، و مسلم: 871","e":"جناب حارث بن نعمان کی صاحبزادی ام ہشام رضی اللہ عنہا بیان کرتی ہیں کہ میں نے سورہ ق رسول اللہ صلی اللہ علیہ وسلم کے منہ مبارک سے سن کر ہی یاد کی ہے۔ آپ اسے لوگوں سے خطاب کرتے وقت ہر خطبہ جمعہ میں پڑھا کرتے تھے۔ سیدنا ابو سعید خدری رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے ایک روز ہمیں خطبہ دیا اور (منبر پر) سورہ ص کی تلاوت کی، سجدہ کی آیت پر پہنچے تو آپ منبر سے نیچے تشریف لائے اور سجدہ کیا۔(صحیح، ابوداود: ۱۴۱۰) سیدنا جابر رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم جب خطبہ ارشاد فرماتے تو آپ کی آنکھیں سرخ ہو جاتیں، آواز گرجدار ہو جاتی اور غصہ (جوش و جذبہ) بڑھ جاتا، یوں محسوس ہوتا گویا آپ کسی لشکر (حملہ آور) سے خبردار کر رہے ہیں۔(صحیح مسلم: ۸۶۷)"}],[1085,"حصین بن عبدالرحمن بیان کرتے ہیں کہ عمارہ بن رویبہ نے بشر بن مروان کو دیکھا کہ وہ جمعہ کے روز اثنائے خطبہ میں ہاتھ اٹھا کر دعا کر رہا تھا (ہاتھ ہلا رہا تھا) تو عمارہ نے کہا: اللہ تعالیٰ ان دونوں چھوٹے (کم مرتبہ) ہاتھوں کو رسوا کرے، میں نے رسول اللہ صلی اللہ علیہ وسلم کو دیکھا ہے کہ آپ اس سے زیادہ نہیں کرتے تھے، ہشیم نے شہادت کی انگلی سے اشارہ کیا (یعنی صرف شہادت کی انگلی اٹھانے پر اکتفا کرتے تھے)۔","",{"k":"أخرجه مسلم: 874","e":"سفیان عن حصین کی سند میں یہ الفاظ ہیں: «وَأَشَارَ بِالسَّبَّابَةِ عِنْدَ الْخَاصِرَةِ» ’’آپ کمر تک انگشت شہادت سے اشارہ کرتے۔‘‘ امام بغوی رحمہ اللہ نے کہا: سیدنا انس رضی اللہ عنہ سے مروی ہے کہ ایک روز نبی صلی اللہ علیہ وسلم جمعے کا خطبہ ارشاد فرما رہے تھے کہ ایک دیہاتی نے کھڑے ہو کر کہا: اے اللہ کے رسول! جانور تباہ ہو گئے، بچے بھوک سے نڈھال ہو گئے، آپ اللہ سے دعا فرمائیں، چنانچہ آپ نے دونوں ہاتھ اٹھائے۔(صحیح بخاری: ۹۳۲) سیدنا انس رضی اللہ عنہ سے مروی ہے کہ نبی صلی اللہ علیہ وسلم کوئی دعا کرتے ہوئے ہاتھ نہیں اٹھاتے تھے سوائے بارش کی دعا کے اور اس میں ہاتھ اتنے بلند اٹھاتے کہ آپ کی بغلوں کی سفیدی دیکھی جاتی۔(صحیح بخاری: ۱۰۳۱، صحیح مسلم: ۸۹۵) امام مالک رحمہ اللہ نے کہا: خطبہ کے دوران میں ہاتھ اٹھانا غیر مشروع اور خلاف سنت ہے اور بارش طلب کرنے کے لیے ہاتھ اٹھانا سنت رسول صلی اللہ علیہ وسلم ہے۔ اگر کوئی خطیب اثنائے خطبہ میں بارش کے حصول کے لیے دعا کرے تو اسے سنت نبوی کی پیروی میں ہاتھ ضرور اٹھانے چاہئیں۔","f":"خطیب کا دوران خطبہ اپنے ہاتھ ہلا ہلا کر لوگوں سے خطاب کرنا خلاف سنت اور خلاف ادب جمعہ ہے، صرف انگشت شہادت سے اشارہ ثابت ہے۔ رہا یہ استدلال کہ اثنائے خطبہ ہاتھ اٹھا کر دعا کرنا ممنوع ہے۔ اگر چہ بعض رواۃ اس طرف گئے ہیں مگر یہ استدلال مرجوح ہے کیونکہ نبی صلی اللہ علیہ وسلم سے ثابت ہے کہ آپ نے استسقاء کے دوران ہاتھ اٹھا کر دعا فرمائی تھی۔(ع، س)"}],[1086,"سیدنا ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ صلی اللہ علیہ وسلم نے فرمایا: ’’جمعے کے دن جب امام خطبہ دے رہا ہو اس وقت اگر تم نے اپنے ساتھی سے کہا: خاموش رہو، تو تم نے فضول گوئی کی۔‘‘","",{"k":"أخرجه البخارى: 934، و مسلم: 851","e":"ایک روایت میں «فقد لغبت» کے الفاظ بھی مذکور ہیں۔ یہ لفظ باب فَعَلَ يَفْعُلُ اور فَعِلَ يَفْعَلُ دونوں سے آتا ہے۔ سیدنا عثمان بن عفان رضی اللہ عنہ نے کہا: جب امام خطبہ دینے کے لیے منبر پر فروکش ہو جائے تو توجہ سے سنو اور خاموش رہو، بلاشبہ امام کی آواز نہ پہنچنے کے باوجود خاموش رہ کر سننے والے کو ویسا ہی اجر و ثواب ملے گا جیسا کہ خاموشی سے خطبہ سماعت کرنے والے کو۔ امام بغوی رحمہ اللہ نے کہا: تمام اہل علم اس بات پر متفق ہیں کہ جب امام خطبہ دے رہا ہو تو بولنا اور گفتگو کرنا ناپسندیدہ ہے، اگر کوئی دوسرا کلام میں مشغول ہو تو اسے اشارے سے خاموش کرایا جائے نہ کہ بول کر۔ سیدنا علی رضی اللہ عنہ کہتے ہیں: جب امام خطبہ دینے کے لیے منبر پر کھڑا ہو جائے تو نماز نہ پڑھی جائے۔ جناب ابن شہاب رحمہ اللہ کہتے ہیں: امام کا جمعہ پڑھانے کے لیے مسجد میں آ جانا نوافل پڑھنے کو ختم کر دیتا ہے اور امام کا گفتگو کرنا ہر قسم کی بات چیت کو منقطع کر دیتا ہے۔ امام زہری رحمہ اللہ کے قول اور سیدنا علی رضی اللہ عنہ کے فرمان کا مطلب یہ ہے کہ ایسا ہرگز نہ کیا جائے کہ مسجد میں موجود ہونے کے باوجود پس و پیش سے کام لیا جائے اور خطیب کے منبر پر براجمان ہونے کے بعد نوافل کی ادائیگی شروع کر دی جائے اور اس طرح خطبہ کا ابتدائی حصہ فوت ہو جائے، البتہ امام کے خطبہ شروع کرنے سے پہلے ضروری بات چیت کرنے میں کوئی حرج نہیں۔","f":"امام زہری رحمہ اللہ اور سیدنا علی رضی اللہ عنہ کے اقوال کا یہ بہترین محمل ہے جو امام رحمہ اللہ نے بیان کر دیا ہے کہ خواہ مخواہ کسل مندی اور سستی کا مظاہرہ نہ کیا جائے کہ پہلے آنے کے باوجود وقت ضائع کر دیا جائے اور امام کی آمد کے بعد جواز سے فائدہ اٹھاتے ہوئے نوافل پڑھنے شروع کر دیے جائیں لیکن اگر کوئی شخص پورے اہتمام کے باوجود کسی وجہ سے لیٹ ہو گیا ہے تو اثنائے خطبہ تحیۃ المسجد پڑھ سکتا ہے، حدیث کے الفاظ یہ ہیں: «إِذَا جَاءَ أَحَدُكُمْ يَوْمَ الْجُمُعَةِ وَالْإِمَامُ يَخْطُبُ فَلْيَرْكَعْ رَكْعَتَيْنِ وَلْيَتَجَوَّزْ فِيهِمَا» ’’جب تم میں سے کوئی جمعہ کے دن آئے اور امام خطبہ دے رہا ہو تو وہ دو رکعتیں ادا کرے اور ان دونوں کو اختصار کے ساتھ پڑھے۔‘‘ (صحیح مسلم: ۸۷۵)۔(ع، س) کیا اثنائے خطبہ میں سلام کہنے والے اور چھینک مارنے والے کو جواب دیا جائے گا؟ بعض آئمہ نے اس سلسلہ میں رخصت کی بات کی ہے مثلاً امام احمد رحمہ اللہ، اسحاق اور ایک روایت کے مطابق امام شافعی رحمہ اللہ وغیرہ جبکہ کچھ دوسرے علماء تابعین نے جواب دینے کو ناپسند جانا ہے، جناب سعید بن مسیب رحمہ اللہ اسی بات کے قائل ہیں۔ امام زہری رحمہ اللہ کہتے ہیں: جب امام منبر سے اتر آئے تو تکبیر تحریمہ کہنے تک گفتگو کر لینے میں کوئی مضائقہ نہیں۔ ابراہیم بن مہاجر کہتے ہیں: میں نے سعید بن جبیر اور ابراہیم نخعی رحمہما اللہ کو محو گفتگو دیکھا جبکہ خطبہ ہو رہا تھا۔ خطبہ مکمل خاموشی سے سننا چاہیے، خطبے کے دوران کسی سے بات کرنا یا اس کی بات کا جواب دینا منع ہے، خطبے کے دوران حاضرین میں سے کوئی شخص اگر امام سے کوئی ضروری بات کہنا چاہتا ہو تو اجازت ہے، جیسے ایک شخص نے خطبے کے دوران میں آ کر رسول اللہ صلی اللہ علیہ وسلم سے بارش کے لیے دعا کی درخواست کی اور اگلے جمعے خطبے کے دوران بارش بند ہونے کی دعا کے لیے درخواست کی گئی (صحیح بخاری: ۹۳۳)۔ اسی طرح رسول اللہ صلی اللہ علیہ وسلم نے سیدنا سلیک رضی اللہ عنہ سے کلام فرمایا۔ جناب سعید بن جبیر اور ابراہیم نخعی رحمہما اللہ کو شاید اس حدیث کا علم نہ ہو یا خطیب سے مناسب فاصلے پر ہوں گے کہ آواز سنائی نہ دیتی ہوگی، بہر حال مسئلہ واضح ہے اور سنت رسول صلی اللہ علیہ وسلم پر عمل ہی اولیٰ اور امت کے اتفاق و اتحاد کا ضامن ہے۔(ع، س)"}]])